// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Türk kültürü, gelenekler, el sanatları, deyim ve atasözlerinin kökenleri (orta).
const ozCulture2Orta = <(String, String, List<String>, String)>[
  ('Bir öğrenci her gün yalnız on sayfa okuyarak bir yılda onlarca kitap bitiriyor. Bu durumu en iyi anlatan atasözü hangisidir?', 'Az az öğrenip çok olur.', ['Ağaç yaşken eğilir.', 'Bin işit, bir söyle.', 'Söz gümüşse sükût altındır.'], 'Düzenli ve küçük adımlarla zamanla büyük birikim elde edilmesi "Az az öğrenip çok olur" sözüyle anlatılır.'),
  ('"Komşu komşunun külüne muhtaçtır." atasözü toplumsal yaşamla ilgili hangi gerçeği vurgular?', 'İnsanlar en küçük şeyler için bile birbirine ihtiyaç duyar.', ['Komşular arasında kıskançlık eksik olmaz.', 'Ateşin sönmemesi için kül saklanmalıdır.', 'Yakın oturanlar sık sık tartışır.'], 'Kül, en değersiz şeylerden biri sayılır; atasözü komşuların bunun için bile birbirine gerek duyduğunu, yardımlaşmanın zorunlu olduğunu anlatır.'),
  ('Aşağıdaki atasözlerinden hangisi ötekilerle aynı temayı işlemez?', 'Sütten ağzı yanan yoğurdu üfleyerek yer.', ['Birlikten kuvvet doğar.', 'Bir elin nesi var, iki elin sesi var, birlikte iş görülür.', 'Yalnız taş duvar olmaz.'], 'Üç atasözü birlik ve dayanışmayı anlatır. "Sütten ağzı yanan..." ise kötü bir deneyimden sonra aşırı temkinli olmayı anlatır.'),
  ('Daha önce bir arkadaşına borç verip parasını geri alamayan biri, artık kimseye ödünç vermeye yanaşmıyor. Bu tutumu anlatan atasözü hangisidir?', 'Sütten ağzı yanan yoğurdu üfleyerek yer.', ['Ak akçe kara gün içindir.', 'Borç yiğidin kamçısıdır.', 'Eden bulur, inleyen ölür.'], 'Bir kez zarar gören kişinin benzer durumlarda gereğinden fazla tedbirli davranması bu atasözüyle anlatılır.'),
  ('"Ak akçe kara gün içindir." atasözündeki "ak akçe" ve "kara gün" sözleri neyi karşılar?', 'Biriktirilmiş para ve sıkıntılı zaman', ['Gümüş takı ve yas günü', 'Temiz kazanç ve kış mevsimi', 'Bağış parası ve bayram günü'], 'Akçe Osmanlı\'nın gümüş parasıdır; "ak akçe" biriktirilen parayı, "kara gün" ise darlık ve sıkıntı zamanını anlatır.'),
  ('"Keskin sirke küpüne zarar." atasözü en çok hangi kişilik özelliğini eleştirir?', 'Aşırı öfke ve sinirlilik', ['Cimrilik', 'Tembellik', 'Aşırı utangaçlık'], 'Çok keskin sirke içinde durduğu küpü bozar; öfkesine hâkim olamayan insan da en çok kendine zarar verir.'),
  ('"Mum dibine ışık vermez." atasözüne en uygun örnek hangisidir?', 'Bütün mahallenin sorununu çözen birinin kendi ailesiyle ilgilenmemesi', ['Elektrik kesildiğinde mum yakılması', 'Akşam olunca işyerlerinin kapanması', 'Bir öğretmenin herkese aynı ödevi vermesi'], 'Atasözü, başkalarına yararı dokunan birinin en yakınlarına yarar sağlayamamasını anlatır.'),
  ('"Atasözü" ile "deyim" arasındaki temel fark hangisidir?', 'Atasözü kalıplaşmış bir yargı ya da öğüt bildirir; deyim çoğunlukla yargı bildirmez.', ['Deyimler yalnız halk şiirinde kullanılır.', 'Atasözlerinin söyleyeni bellidir.', 'Deyimler her zaman en az iki cümleden oluşur.'], 'Atasözleri genellikle tam bir yargı ya da öğüt içerir. Deyimler ise çoğu kez mastar biçiminde, mecaz anlamlı kalıp sözlerdir.'),
  ('"Su testisi su yolunda kırılır." atasözünün anlamı nedir?', 'Tehlikeli bir işle uğraşan kişi er geç o işin zararını görür.', ['Testiler dikkatli taşınmalıdır.', 'Su taşımak çok yorucu bir iştir.', 'Eski eşyalar yenileriyle değiştirilmelidir.'], 'Sürekli su taşıyan testinin bir gün yolda kırılması gibi, riskli bir işi sürdüren de sonunda o işten zarar görür.'),
  ('"Kaz gelecek yerden tavuk esirgenmez." atasözü hangi hesabı anlatır?', 'Büyük bir kazanç için küçük bir fedakârlıktan kaçınılmaz.', ['Kümes hayvanları birlikte beslenmelidir.', 'Misafire her zaman tavuk ikram edilir.', 'Küçük kazanç büyük kazançtan iyidir.'], 'Tavuk küçük bir bedeli, kaz ise daha büyük bir kazancı simgeler. Daha fazlasını elde etmek için az bir şey vermekten çekinilmez.'),
  ('"Bir musibet bin nasihatten iyidir." atasözü neyi vurgular?', 'Yaşanan bir kötü deneyimin pek çok öğütten daha öğretici olduğunu', ['Öğüt vermenin insanı yorduğunu', 'Kötü olayların hep art arda geldiğini', 'Bin kişiye öğüt verilmesi gerektiğini'], 'Musibet, başa gelen bela demektir. İnsan, kendi başına gelen bir kötülükten, dinlediği nice öğütten daha çok ders alır.'),
  ('"Ağlamayan çocuğa meme vermezler." atasözü hangi durumda kullanılır?', 'İsteğini dile getirmeyen kişinin ihtiyacının karşılanmadığı durumlarda', ['Bebeklerin beslenme saatleri düzenlenirken', 'Çocukların ağlamasına izin verilmediğinde', 'Annelerin işten erken dönmesi istendiğinde'], 'Atasözü, derdini ya da isteğini söylemeyenin ihtiyacının fark edilmeyeceğini, hakkını aramak gerektiğini anlatır.'),
  ('"Mart kapıdan baktırır, kazma kürek yaktırır." atasözü hangi gözleme dayanır?', 'Mart ayında havanın beklenmedik biçimde soğuyabilmesine', ['Mart ayında tarım aletlerinin onarılmasına', 'Martta çiftçilerin tarlaya erken çıkmasına', 'Mart ayının yılın en kurak ayı olmasına'], 'Mart ayı bahar sanılsa da ani soğuklar yaşanabilir; insanlar yakacak bitince kazma küreğin sapını bile yakmak zorunda kalır.'),
  ('"Eşek hoşaftan ne anlar?" sözü hangi kişiler için söylenir?', 'Bir şeyin değerini bilmeyen, inceliğini anlamayan kişiler', ['Tatlı yemeyi sevmeyenler', 'Hayvanları besleyen çobanlar', 'Sofrada az yiyen misafirler'], 'Söz, değerli ya da ince bir şeyin onu anlamaktan uzak birine sunulmasının boşuna olduğunu anlatır.'),
  ('Aşağıdaki atasözlerinden hangisi "doğruluk" temasını işler?', 'Doğru söyleyeni dokuz köyden kovarlar.', ['Kervan yolda düzülür.', 'Acele işe şeytan karışır.', 'Aç ayı oynamaz.'], 'Bu atasözü, gerçeği açıkça söyleyen kişinin sevilmediğini ve dışlandığını anlatır; ana teması doğruluktur.'),
  ('"Kervan yolda düzülür." atasözü hangi yaklaşımı anlatır?', 'Eksikliklerin iş yapılırken zamanla giderileceğini', ['Yolculuğa hazırlık yapmadan çıkılmaması gerektiğini', 'Kervanların en düz yolu izlediğini', 'Ticaretin yalnız gezginlere ait olduğunu'], 'Bir işe başlarken her şey kusursuz olmayabilir; aksaklıklar süreç içinde düzeltilir.'),
  ('"Aç ayı oynamaz." atasözünün anlamı hangisidir?', 'İhtiyacı karşılanmayan kimseden iş beklenmez.', ['Ayılar yalnız tok olduklarında saldırır.', 'Aç kalan biri her işi yapmaya razıdır.', 'Oyun oynamak için önce yemek yenmelidir.'], 'Eskiden ayı oynatanların hayvanı beslemeden oynatamaması gibi, hakkı verilmeyen insandan da verim beklenemez.'),
  ('"Isıracak it dişini göstermez." atasözü aşağıdakilerden hangisine karşı uyarır?', 'Asıl tehlikeli olanın niyetini belli etmeyen kişi olduğuna', ['Köpeklerin her zaman saldırgan olduğuna', 'Dişleri bakımsız insanlardan uzak durmaya', 'Sürekli tehdit savuran herkesin zararlı olduğuna'], 'Gerçekten zarar verecek kişi bunu açıkça göstermez; gizli düşman daha tehlikelidir.'),
  ('"Kendi düşen ağlamaz." atasözü hangi durumda söylenir?', 'Kişi kendi hatasıyla bir sıkıntıya düştüğünde', ['Çocuklar oyun oynarken yaralandığında', 'Biri başkasının yüzünden haksız yere zarar gördüğünde', 'Yaşlılar bastonsuz yürüdüğünde'], 'Kendi yanlışının sonucunu yaşayan kişinin şikâyet etmeye ya da başkasını suçlamaya hakkı yoktur.'),
  ('"Rüzgâr eken fırtına biçer." atasözünün anlamı nedir?', 'Kötülük yapan, yaptığından çok daha büyük bir kötülükle karşılaşır.', ['Rüzgârlı havalarda tohum ekilmez.', 'Hava durumu tarımı doğrudan etkiler.', 'Fırtınadan sonra rüzgâr diner.'], 'Küçük bir kötülüğün sonucu, onu yapana katlanarak geri döner.'),
  ('"Burnundan kıl aldırmamak" deyimi nasıl bir kişiyi tanımlar?', 'Kimsenin kendisine söz söylemesine izin vermeyen, kibirli birini', ['Temizliğine çok dikkat eden birini', 'Hiç hastalanmayan birini', 'Kokulara karşı duyarlı birini'], 'Deyim, kendini beğenmiş, en küçük eleştiriyi bile kabul etmeyen kişiler için kullanılır.'),
  ('"Göz boyamak" deyimi aşağıdaki durumların hangisine uygundur?', 'Denetim öncesi yalnız görünen yerleri temizleyip işin aslını gizlemek', ['Bir resmi renkli boyalarla tamamlamak', 'Makyaj yaparak bir gösteriye çıkmak', 'Gözlük camlarını renklendirmek'], 'Göz boyamak, gerçeği gizleyip bir şeyi olduğundan iyi göstererek aldatmaktır.'),
  ('"Kırk fırın ekmek yemek" deyimi ne anlatır?', 'Bir konuda daha çok deneyim kazanmak gerektiğini', ['Çok iştahlı olmayı', 'Fırıncılık mesleğini öğrenmeyi', 'Uzun süre aç kalmayı'], 'Bu deyim, kişinin bir işi başarabilmesi için önünde daha uzun bir deneyim süreci bulunduğunu anlatır.'),
  ('"Pire için yorgan yakmak" deyimine en uygun örnek hangisidir?', 'Küçük bir arıza yüzünden çalışan bilgisayarı tümden çöpe atmak', ['Kışın üşümemek için kalın yorgan almak', 'Evdeki haşereleri ilaçla yok etmek', 'Eski yorganı yenisiyle değiştirmek'], 'Küçük bir zarardan kurtulmak için çok daha büyük bir zarara razı olmak bu deyimle anlatılır.'),
  ('"Dokuz doğurmak" deyimi hangi ruh hâlini anlatır?', 'Bir şeyi sabırsızlıkla ve sıkıntıyla beklemek', ['Çok kalabalık bir ailede büyümek', 'Ardı ardına başarı kazanmak', 'Gereksiz yere övünmek'], 'Deyim, bir sonucu beklerken büyük bir sıkıntı ve sabırsızlık çekmeyi anlatır.'),
  ('"Çam devirmek" deyimiyle aynı anlama gelen deyim hangisidir?', 'Pot kırmak', ['Çam sakızı gibi yapışmak', 'Taş kesilmek', 'Dal budak salmak'], 'İki deyim de yerinde olmayan bir söz ya da davranışla karşısındakini kırmak, gaf yapmak anlamındadır.'),
  ('"Kırk dereden su getirmek" deyimi nasıl bir tutumu anlatır?', 'Bir işi yapmamak için türlü bahaneler uydurmayı', ['Çok çalışkan olup uzak yerlerden sırtında su taşımayı', 'Bir sözü sık sık değiştirmeyi', 'Konuşurken konudan konuya atlamayı'], 'Deyim, bir şeyden kaçınmak ya da bir isteği reddetmek için sayısız gerekçe ileri sürmeyi anlatır.'),
  ('"Mangalda kül bırakmamak" deyimi nasıl bir kişiyi tanımlar?', 'Büyük laflar edip yapamayacağı işlerle övünen birini', ['Evini çok temiz tutan birini', 'Mangal başında usta olan birini', 'Az konuşup çok iş yapan birini'], 'Bu deyim, yapamayacağı şeyleri yapabilirmiş gibi övünüp ileri geri konuşanlar için kullanılır.'),
  ('"Kırk katır mı, kırk satır mı?" sözü hangi durumu anlatır?', 'İki kötü seçenekten birini seçmek zorunda kalmayı', ['Çok zengin olup ne alacağını bilememeyi', 'Bir işi kırk kez denemeyi', 'Hayvan pazarında pazarlık etmeyi'], 'Söz, kişiye sunulan iki seçeneğin de kötü olduğu, yine de birinin seçilmesinin zorunlu olduğu durumlarda kullanılır.'),
  ('"Çam sakızı çoban armağanı" sözü bir hediye sunulurken hangi anlamda söylenir?', 'Hediyenin küçük ama içten olduğunu belirtmek için', ['Hediyenin çok pahalı olduğunu ve özenle seçildiğini vurgulamak için', 'Hediyenin geri verilmesini istemek için', 'Hediyenin dağdan getirildiğini söylemek için'], 'Yoksul çobanın verebileceği tek şey çam sakızıdır; söz, armağanın değeri az olsa da gönülden verildiğini anlatır.'),
  ('"Kuş sütü eksik" sözü bir sofra için söylendiğinde ne anlatır?', 'Sofrada akla gelebilecek her yiyeceğin bulunduğunu', ['Sofrada süt ürünlerinin olmadığını', 'Yemeklerin kuş etinden yapıldığını', 'Sofranın aceleyle kurulduğunu'], 'Kuş sütü var olmayan bir şeyi simgeler; ondan başka her şeyin bulunması büyük bolluğu anlatır.'),
  ('"Bindiği dalı kesmek" deyimine uygun davranış hangisidir?', 'Geçimini sağladığı işyerinin itibarını sosyal medyada zedelemek', ['Bahçedeki kuru dalları budamak', 'Riskli bir işe girişmeden önce plan yapmak', 'Ağaca çıkmadan önce merdiven kurmak'], 'Kişinin kendisine yararı dokunan kişi ya da kuruma zarar vermesi, kendi kuyusunu kazmasıdır.'),
  ('"Ekmeğini taştan çıkarmak" deyimi nasıl bir kişiyi anlatır?', 'En zor koşullarda bile geçimini sağlayabilen becerikli birini', ['Taş ocağında çalışan birini', 'Ekmeği kendi evinde pişiren birini', 'Az yemekle yetinen birini'], 'Deyim, çalışkanlığı ve becerisi sayesinde her ortamda kazancını elde edebilen kişiler için kullanılır.'),
  ('"Göbeğini kendi kesmek" deyimi hangi anlamda kullanılır?', 'Kimseden yardım almadan işini kendi başına görmek', ['Kendi kendine zarar vermek', 'Ailesinden erken ayrılmak', 'Doğum gününü kendi kutlamak'], 'Kişinin başkasına muhtaç olmadan kendi sorununu kendisinin çözmesi bu deyimle anlatılır.'),
  ('"Tuzu kuru" deyimi nasıl bir kişiyi tanımlar?', 'Herkes sıkıntıdayken durumu iyi olan, rahat birini', ['Yemeklerine tuz koymayan birini', 'Cimri ve eli sıkı birini', 'Kuraklıktan etkilenen çiftçiyi'], 'Eskiden tuzun nemden korunması önemliydi; tuzu kuru olan kişi, çevresi zor durumdayken sıkıntı çekmeyen kimsedir.'),
  ('"Damdan düşer gibi" söylemek hangi tarzı anlatır?', 'Bir sözü hiçbir hazırlık yapmadan, birdenbire ortaya atmayı', ['Bir haberi çok yavaş ve dikkatli vermeyi', 'Yüksek bir yerden bağırmayı', 'Söylenenleri sürekli yinelemeyi'], 'Deyim, uygun zamanı ve ortamı gözetmeden, pat diye söylenen sözler için kullanılır.'),
  ('"Pabucu dama atılmak" deyiminin kökeni olarak yaygın biçimde hangi esnaf geleneği gösterilir?', 'Ahi loncalarında kötü mal yapan ayakkabıcının pabucunun dama atılması', ['Düğünlerde gelinin ayakkabısının kayınvalideye verilmesi ve saklanması geleneği', 'Camiye girerken çıkarılan ayakkabıların çatıda kurutulması', 'Kış başında eski ayakkabıların toplanıp yoksullara dağıtılması'], 'Ahilik geleneğinde kusurlu iş çıkaran ustanın ayakkabısının dama atılması onun itibarını yitirdiğini gösterirdi. Deyim bugün gözden düşmeyi anlatır.'),
  ('Yeniçeri Ocağı ile ilişkilendirilen "kazan kaldırmak" deyimi bugün hangi anlamda kullanılır?', 'Ayaklanmak, karşı çıkmak', ['Yemek pişirip dağıtmak', 'Ağır bir yükü tek başına taşımak', 'Bir kutlama için hazırlık yapmak'], 'Yeniçeriler hoşnutsuzluklarını, ocağın simgesi olan kazanları devirerek ya da kaldırarak gösterirdi. Deyim bu yüzden isyanı anlatır.'),
  ('"Nalları dikmek" deyimi neden ölmek anlamında kullanılır?', 'Ölen atın sırt üstü yatıp ayaklarının, yani nallarının havaya kalkmasından', ['Nalbantın işini bitirince nalları duvara asmasından', 'Eski mezar taşlarına nal biçimi verilmesinden', 'At yarışlarında kaybeden atın nallarının sökülmesinden'], 'Ölen at yere yıkıldığında nallı ayakları havaya dikilir; deyim bu görüntüden doğmuş ve ölmenin kaba bir anlatımı olmuştur.'),
  ('Bir şakayı o kadar abartıyor ki arkadaşı gerçekten kırılıyor. Bu kişi için hangi deyim uygundur?', 'Kantarın topuzunu kaçırmak', ['İpe un sermek', 'Kulağına küpe olmak', 'Hapı yutmak'], 'Kantarın topuzunu kaçırmak, bir davranışta ölçüyü aşmak ve aşırıya kaçmak anlamına gelir.'),
  ('"Hem nalına hem mıhına vurmak" deyimi hangi zanaatten gelir?', 'Nalbantlık', ['Kalaycılık', 'Çömlekçilik', 'Semercilik'], 'Nalbant, atın nalını çakarken hem nala hem mıha, yani çiviye vurur. Deyim iki karşı tarafı da idare etmeyi anlatır.'),
  ('"İki dirhem bir çekirdek" deyimi kimin için söylenir?', 'Çok şık ve özenle giyinmiş biri için', ['Çok cimri biri için', 'Fazla zayıf biri için', 'Kuyumcu dükkânı işleten zengin biri için'], 'Dirhem ve çekirdek, kuyumcuların kullandığı küçük ağırlık ölçüleridir; deyim tam ölçüsünde, kusursuz giyinmeyi anlatır.'),
  ('"Kalayı basmak" deyimi hangi meslekle ilgilidir ve bugün ne anlamda kullanılır?', 'Kalaycılıkla; birine ağır sözler söyleyip azarlamak anlamında', ['Demircilikle; bir işi aceleyle bitirmek anlamında', 'Fırıncılıkla; ekmeği fazla pişirmek anlamında', 'Boyacılıkla; eski bir eşyayı yenilemek anlamında'], 'Kalaycı, kabın üzerine kalayı sertçe sürerek kaplardı. Deyim bu sert hareketten esinlenerek birini haşlamayı, sövüp saymayı anlatır.'),
  ('"Mürekkep yalamış" deyimi nasıl bir kişiyi tanımlar?', 'Okumuş, eğitim görmüş birini', ['Yazısı çok kötü birini', 'Kâtiplik yapan yaşlı ve titiz birini', 'Söz dinlemeyen bir çocuğu'], 'Eskiden kamış kalemle yazanların ağızlarına mürekkep bulaşabilirdi. Deyim, okuyup yazmış, bilgili kişiler için kullanılır.'),
  ('"İpliği pazara çıkmak" deyimi hangi zanaatten esinlenmiştir?', 'Dokumacılık', ['Ayakkabıcılık', 'Çömlekçilik', 'Bakırcılık'], 'Pazara çıkan ipliğin kalitesi herkesçe görülürdü. Deyim, birinin gizli kusurlarının ve kötü yanlarının ortaya çıkmasını anlatır.'),
  ('"Haraç mezat satmak" deyimindeki "mezat" ne anlama gelir?', 'Açık artırma', ['Gizli anlaşma', 'Vergi ödemesi', 'Peşin satış'], 'Mezat, malın açık artırmayla satılmasıdır. Deyim, bir şeyi değerinin çok altında, yok pahasına satmayı anlatır.'),
  ('"Mihenk taşı" sözü kökeninde hangi meslekte kullanılan bir araçtır?', 'Kuyumculuk', ['Taş ustalığı', 'Değirmencilik', 'Mimarlık'], 'Mihenk taşı, altının ayarını anlamak için üzerine sürtüldüğü sert, koyu bir taştır. Mecazen bir şeyin değerini ölçmeye yarayan ölçütü anlatır.'),
  ('"Turna gözünden vurmak" deyimi bugün hangi anlamda kullanılır?', 'Bir işte en uygun ve kazançlı olanı tam isabetle elde etmek', ['Bir kuşu avlamak için saatlerce pusuda beklemek', 'Uzaktaki bir şeyi çıplak gözle görebilmek', 'Birini sert bakışlarıyla korkutmak'], 'Avcılıkta hedefi en küçük noktadan vurmak büyük ustalıktır. Deyim, istenen şeyi en iyi biçimde ve tam zamanında yakalamayı anlatır.'),
  ('"Ye kürküm ye" sözü hangi fıkradan doğmuştur ve neyi eleştirir?', 'Nasreddin Hoca\'nın kürkünü yemeğe batırdığı fıkradan; insanlara giyimlerine göre değer verilmesini', ['Keloğlan\'ın kürkünü pazarda sattığı masaldan; açgözlülüğü', 'Köroğlu\'nun kürkünü düşmana bıraktığı destandan; korkaklığı', 'İncili Çavuş\'un saraya kürksüz gittiği hikâyeden; savurganlığı'], 'Eski giysiyle gittiği düğünde ilgi görmeyen Hoca, kürkle dönünce baş köşeye oturtulur ve yemeği kürküne ikram eder. Söz, görünüşe göre değer biçmeyi eleştirir.'),
  ('"Parayı veren düdüğü çalar." sözünün kökeni olan fıkrada çocuklardan yalnız birine düdük getirilmesinin nedeni nedir?', 'Yalnız o çocuğun parayı önceden vermiş olması', ['Diğer çocukların düdük çalmayı bilmemesi', 'O çocuğun Hoca\'nın en yakın ve en sevdiği komşusu olması', 'Pazarda yalnız tek düdük kalmış olması'], 'Pazara giden Hoca\'dan pek çok çocuk düdük ister ama yalnız biri parasını verir; Hoca da yalnız ona düdük getirir. Söz, bedeli ödeyenin söz sahibi olduğunu anlatır.'),
  ('"Kaş yapayım derken göz çıkarmak" deyimine en uygun örnek hangisidir?', 'Çizilen bir masayı onarmaya çalışırken tablayı çatlatmak', ['Yeni bir işe başlarken plan yapmayı unutmak', 'Bir arkadaşın doğum gününü hatırlamamak', 'Alışverişte gereğinden fazla ürün almak'], 'Bir şeyi düzeltmek isterken onu daha da bozmak bu deyimle anlatılır.'),
  ('"Eşeğini sağlam kazığa bağlamak" deyimi nasıl bir tutumu anlatır?', 'Önlemini önceden alıp işini sağlama bağlamak', ['Hayvanlarına çok iyi bakan çalışkan bir köylü olmak', 'İnatçı insanlarla tartışmaya girmemek', 'Yolculuğa çıkmadan önce dinlenmek'], 'Kazığa iyi bağlanan eşek kaçmaz; deyim, ileride zarar görmemek için güvenceye almayı anlatır.'),
  ('"Kurt kocayınca köpeklerin maskarası olur." atasözü neyi anlatır?', 'Güçlü olan biri güçsüz düşünce eskiden korkanların alay konusu olur.', ['Yaşlı kurtların sürüye saldırmaktan vazgeçtiği', 'Köpeklerin kurtlardan daha zeki olduğu', 'Çobanların yaşlı köpeklerini sürüden ayırdığı'], 'Bir zamanlar korkulan kişinin gücünü yitirince küçük görülmesi bu atasözüyle anlatılır.'),
  ('"Koyun can derdinde, kasap et derdinde." atasözü hangi durumu anlatır?', 'Birinin büyük sıkıntısıyla başkasının yalnız kendi çıkarını düşünmesini', ['Hayvancılığın zor bir meslek olduğunu', 'Kasapların hayvanlara iyi baktığını', 'Kurban bayramının önemini'], 'Biri yaşam kaygısı taşırken öteki yalnızca ondan sağlayacağı yararı düşünür; atasözü bu duyarsızlığı eleştirir.'),
  ('"Zurnanın zırt dediği yer" sözü neyi anlatır?', 'Bir işin en kritik, en zor noktasını', ['Bir düğünün en eğlenceli anını', 'Bir şarkının en yüksek sesli bölümünü', 'Bir kasabanın en kalabalık meydanını'], 'Zurnada en zor çalınan ve sesi en çok çatlayan yer, mecazen bir işin düğümlendiği, ustalık gerektiren noktayı anlatır.'),
  ('"Davul bile dengi dengine" sözü hangi konuda öğüt verir?', 'Evlenecek kişilerin denk olması gerektiği konusunda', ['Müzik aletlerinin özenle seçilmesi konusunda', 'Düğünlerde çalgıcıların sayısı konusunda', 'Yükün hayvanlara eşit yüklenmesi konusunda'], 'Davulun iki yüzü bile birbirine denk olmalıdır; söz özellikle evlilikte eşlerin birbirine uygun olmasını öğütler.'),
  ('"Kel başa şimşir tarak" sözü neyi alaya alır?', 'İhtiyaca uygun olmayan gereksiz lüksü', ['Saç bakımına özen göstermeyi', 'Şimşir ağacının değerli olmasını', 'Yaşlıların saçlarını taramasını'], 'Saçı olmayan bir başa değerli şimşir tarak almak boşunadır; söz, yerini bulmayan süslü ve pahalı şeyleri anlatır.'),
  ('"Kalıbını basmak" deyimi ne anlama gelir?', 'Bir şeyin doğruluğundan çok emin olup kefil olmak', ['Bir eşyanın kopyasını çıkarmak', 'Ekmek hamurunu biçimlendirmek', 'Birinin yerini almak'], 'Deyim, söylenen şeyin kesinliğine o kadar güvenmeyi anlatır ki kişi bunun için kendini ortaya koyar.'),
  ('"Damgasını vurmak" deyimi bugün hangi anlamda kullanılır?', 'Bir döneme ya da olaya etkisini belirgin biçimde bırakmak', ['Bir mektubu postaneden göndermek', 'Hayvanları sahiplerine göre işaretlemek', 'Bir belgeyi resmî olarak onaylamak'], 'Damga, bir şeyin üzerine kalıcı iz bırakır; deyim bu yüzden bir kişinin ya da olayın bir şey üzerinde belirleyici iz bırakmasını anlatır.'),
  ('"Tellal çağırmak" deyimindeki tellal kimdir?', 'Çarşıda bağırarak duyuru yapan kimse', ['Köylerde su dağıtan kimse', 'Saray kapısını bekleyen kimse', 'Kervanlara yol gösteren kimse'], 'Tellal, eskiden çarşı ve mahallelerde duyuru yapan, satılık malları ilan eden kişiydi. Deyim, bir şeyi herkese yaymayı anlatır.'),
  ('Simetrik çift düğüm olarak bilinen ve Türk düğümü diye de anılan halı düğümü hangi adla tanınır?', 'Gördes düğümü', ['Tibet düğümü', 'Sine düğümü', 'İspanyol düğümü'], 'Gördes düğümünde iplik iki çözgü telinin çevresine simetrik biçimde dolanır. Asimetrik tek düğüm ise Sine ya da İran düğümü olarak bilinir.'),
  ('Altay Dağları\'nda bir kurganda bulunan, bilinen en eski düğümlü halı olarak kabul edilen ve Gördes düğümüyle dokunmuş halı hangisidir?', 'Pazırık halısı', ['Hereke ipek halısı', 'Uşak halısı', 'Lotto halısı'], 'Pazırık halısı MÖ 5. ile 4. yüzyıllar arasına tarihlenir ve donmuş kurgan sayesinde korunmuştur. Bugün St. Petersburg\'daki Ermitaj Müzesi\'ndedir.'),
  ('Kök boyacılıkta kırmızı renk geleneksel olarak hangi bitkiden elde edilir?', 'Kökboya', ['Cehri meyvesi ve ceviz kabuğu karışımı', 'Çivit otu yaprakları', 'Nar çiçeği ve sumak yaprağı'], 'Kökboya bitkisinin kökleri kırmızı tonları verir. Çivit mavi, cehri ise sarı renk elde etmede kullanılır.'),
  ('Anadolu kilimlerinde kollarını beline koymuş bir kadın figürünü andıran "elibelinde" motifi genellikle neyi simgeler?', 'Bereket ve analık', ['Savaş ve kahramanlık', 'Göç ve yolculuk', 'Yas ve ayrılık'], 'Elibelinde motifi kadını, doğurganlığı ve bereketi simgeler. Koçboynuzu ise daha çok gücü ve erkekliği anlatır.'),
  ('Kilimlerde gücü, kahramanlığı ve erkekliği simgeleyen motif hangisidir?', 'Koçboynuzu', ['Saç bağı', 'Elibelinde ve bereket', 'Küpe'], 'Koçboynuzu motifi hayvancı toplumlarda güç ve erkekliği temsil eder. Saç bağı ve küpe ise evlilik isteğiyle ilgili motiflerdir.'),
  ('Anadolu dokumalarında görülen "hayat ağacı" motifi en çok hangi kavramla ilişkilendirilir?', 'Ölümsüzlük', ['Kıtlık ve yoksulluk', 'Komşuluk ilişkileri', 'Ticaret ve kazanç'], 'Hayat ağacı, yer ile göğü bağlayan ve sonsuz yaşamı simgeleyen eski bir motiftir.'),
  ('Bir halının dayanıklılığı ve desen inceliği hakkında bilgi veren en önemli teknik ölçüt hangisidir?', 'Birim alandaki düğüm sayısı', ['Halının saçaklarının uzunluğu', 'Halının ağırlığının rengine oranı', 'Dokunduğu tezgâhın yüksekliği'], 'Düğüm sıklığı arttıkça motifler daha ayrıntılı işlenebilir ve halı daha sık, dayanıklı olur.'),
  ('Ebru yapımında suyu kıvamlandırmak için kullanılan ve geven bitkisinden elde edilen madde nedir?', 'Kitre', ['Arap zamkı', 'Nişasta', 'Jelatin'], 'Kitre, geven bitkisinin salgısından elde edilen bir zamktır; suya katılınca boyaların yüzeyde yüzmesini sağlayan kıvamı verir.'),
  ('Ebru boyalarının suyun üzerinde dağılıp açılabilmesi için boyalara ne eklenir?', 'Sığır ödü', ['Zeytinyağı', 'Yumurta sarısı', 'Bal mumu'], 'Öd, boyanın yüzey gerilimini değiştirerek kitreli suyun üzerinde yayılmasını sağlar. Öd miktarı boyanın ne kadar açılacağını belirler.'),
  ('Kâğıdı batırmadan önce yüzeye serpilen boyalarla elde edilen, herhangi bir biçim verilmemiş en temel ebru türü hangisidir?', 'Battal ebru', ['Hatip ebrusu', 'Çiçekli ebru', 'Gelgit ebrusu'], 'Battal ebru, boyaların serpilip doğrudan kâğıda alındığı temel ebrudur. Diğer türler bu zemin üzerinde ek işlemlerle oluşturulur.'),
  ('Hat sanatında kullanılan "aharlı kâğıt" nedir?', 'Yüzeyi nişasta ve yumurta akıyla kaplanıp perdahlanmış kâğıt', ['Ebru desenleriyle süslenmiş renkli kâğıt', 'Altın tozuyla kenarları süslenmiş kâğıt', 'Ağaç kabuğundan elle yapılmış kalın kâğıt'], 'Ahar, kâğıdın mürekkebi emmemesi ve hatalı yazının silinebilmesi için sürülen kaplamadır; ardından kâğıt mühre ile parlatılır.'),
  ('Osmanlı\'da hat sanatının kurucusu sayılan ve "kıbletü\'l-küttâb" (yazarların kıblesi) diye anılan hattat kimdir?', 'Şeyh Hamdullah', ['Mimar Sinan ya da Davud Ağa', 'Levni', 'Itri'], 'Şeyh Hamdullah 15. ve 16. yüzyıllarda yaşamış, Osmanlı\'ya özgü hat üslubunu oluşturmuştur.'),
  ('Hat sanatında öğrencinin başarısını onaylayıp ona kendi imzasıyla yazı yazma izni veren belgeye ne denir?', 'İcazet', ['Berat', 'Padişah fermanı', 'Hilye'], 'İcazet, hocanın öğrencisine verdiği bir tür diplomadır. Bu belgeyi alan hattat eserlerine imza atabilir.'),
  ('Hat eğitiminde hocanın öğrenciye yazdığı örnek yazıyı öğrencinin defalarca taklit ederek çalışmasına ne ad verilir?', 'Meşk', ['İstif', 'Kıta', 'Murakkaa'], 'Meşk, ustanın örneğini izleyerek yapılan yazı alıştırmasıdır. Türk sanat eğitiminde usta-çırak ilişkisinin temelidir.'),
  ('Osmanlı\'da fermanların ve resmî belgelerin yazımında kullanılan, Divan-ı Hümayun ile özdeşleşmiş yazı türü hangisidir?', 'Divani', ['Kûfi', 'Nesih', 'Muhakkak'], 'Divani yazı, adını Divan-ı Hümayun\'dan alır. Harflerin iç içe geçmesiyle sahteciliği zorlaştırdığı için resmî belgelerde tercih edilmiştir.'),
  ('Günlük yazışmalarda hızlı yazılabilmesiyle öne çıkan, süslemesi en az olan yazı türü hangisidir?', 'Rika', ['Sülüs', 'Celî divani', 'Muhakkak'], 'Rika, kısa ve sade harfleriyle hızlı yazılmaya uygundur. Bu yüzden gündelik yazışmalarda ve okullarda yaygın biçimde kullanılmıştır.'),
  ('Kitap ve Kur\'an yazımında okunaklılığı nedeniyle en çok tercih edilen yazı türü hangisidir?', 'Nesih', ['Kûfi', 'Divani', 'Celî sülüs'], 'Nesih yazı açık, düzenli harfleriyle küçük boyutta bile kolay okunur; bu yüzden kitap yazımında yaygınlaşmıştır.'),
  ('Osmanlı sarayında kitap süsleme, minyatür ve desen çalışmalarının yapıldığı atölyeye ne ad verilirdi?', 'Nakkaşhane', ['Tophane', 'Darphane', 'Saray kütüphanesi'], 'Nakkaşhane\'de nakkaşlar, müzehhipler ve minyatür ustaları saray için çalışırdı; Osmanlı süsleme üslubu burada biçimlenmiştir.'),
  ('Osmanlı minyatürünü Avrupa resminden ayıran temel özellik hangisidir?', 'Derinlik ve perspektif kullanılmaması', ['Yalnız yağlı boya kullanılması', 'Figürlerin hiç yer almaması', 'Yalnız manzara çizilmesi'], 'Minyatürde figürler ve nesneler düzlemsel işlenir; uzaktaki nesne küçültülmez, perspektif ve ışık-gölge çok az kullanılır.'),
  ('Cami, saray ve köşklerin duvar ve tavanlarına fırçayla yapılan geleneksel süslemeye ne ad verilir?', 'Kalemişi', ['Tezhip', 'Kündekari', 'Telkari'], 'Kalemişi, sıva ya da ahşap yüzeylere fırçayla uygulanan boyalı süslemedir.'),
  ('İstanbul\'da iç duvarlarının neredeyse tamamı İznik çinileriyle kaplı olmasıyla ünlü, Mimar Sinan eseri cami hangisidir?', 'Rüstem Paşa Camii', ['Nusretiye Camii', 'Ortaköy Camii', 'Dolmabahçe Camii ve külliyesi'], 'Rüstem Paşa Camii, 16. yüzyıl İznik çinilerinin en zengin örneklerinden birini barındırır. Diğer camiler daha geç dönemin barok ve ampir üslubundadır.'),
  ('Beykoz camcılığında renkli ve beyaz şeritlerin spiral biçimde iç içe geçtiği, adını bülbül gözünden alan cam türü hangisidir?', 'Çeşm-i bülbül', ['Tombak', 'Opalin', 'Savat'], 'Çeşm-i bülbül, Farsçada "bülbül gözü" demektir. 19. yüzyılda İstanbul\'da üretilen bu camlar ince şerit desenleriyle tanınır.'),
  ('Geleneksel mavi nazar boncuklarının elde üretimiyle tanınan Nazarköy hangi ile bağlıdır?', 'İzmir', ['Nevşehir', 'Kütahya', 'Bursa'], 'Kemalpaşa ilçesine bağlı Nazarköy\'de cam ustaları boncukları ocakta eritilmiş camdan tek tek üretir.'),
  ('Bakır kapların düzenli olarak kalaylanmasının temel nedeni nedir?', 'Bakırın yiyeceklerle tepkimeye girip sağlığa zararlı bileşikler oluşturmasını önlemek', ['Kapların daha hafif olmasını sağlamak', 'Bakırın rengini kırmızıdan sarıya çevirmek', 'Kapların ateşte daha çabuk ısınmasını engellemek'], 'Bakır asitli yiyecekler ve nemle tepkimeye girerek zararlı bileşikler oluşturabilir. İç yüzeye sürülen kalay bu teması keser.'),
  ('İnce altın ya da gümüş tellerin hasır örgüsü gibi örülmesiyle yapılan bilezikleriyle ünlü il hangisidir?', 'Trabzon', ['Kütahya', 'Afyonkarahisar', 'Tokat'], 'Trabzon hasır bileziği, tellerin el emeğiyle hasır dokusunda örülmesiyle yapılır ve yöreye özgü bir kuyumculuk ürünüdür.'),
  ('Sedef kakma ve bakırcılık gibi el sanatlarıyla tanınan, Güneydoğu Anadolu\'daki il hangisidir?', 'Gaziantep', ['Muğla', 'Bolu', 'Kırklareli'], 'Gaziantep, sedef kakmalı ahşap eşyaları ve bakırcılar çarşısıyla bu el sanatlarının önemli merkezlerinden biridir.'),
  ('Anadolu\'da "oya dili" kavramı neyi anlatır?', 'Kadınların oyaların motif ve renkleriyle duygularını ifade etmesini', ['Oya yapımında kullanılan özel terimlerin bir sözlükte toplanıp öğretilmesini', 'Oyaların hangi yörede yapıldığını gösteren etiketleri', 'Oya ustalarının çıraklara verdiği yazılı kuralları'], 'Geleneksel toplumda kadınlar sevinç, özlem, kırgınlık gibi duygularını açıkça söylemek yerine başörtüsündeki oyanın motifi ve rengiyle anlatabilirdi.'),
  ('Tokat yazmalarında desen kumaşa nasıl aktarılır?', 'Oyulmuş tahta kalıplarla basılarak', ['Kumaşa iğneyle işlenerek', 'Dokuma sırasında renkli iplik katılarak', 'Fırçayla serbest çizilerek'], 'Yazmacılar ağaçtan oyulmuş kalıpları boyaya batırıp kumaşa bastırır; her renk için ayrı kalıp kullanılabilir.'),
  ('Keçeyi dokuma kumaşlardan ayıran temel özellik hangisidir?', 'İplik hâline getirilmeden, yün liflerinin kenetlenmesiyle oluşması', ['Yalnızca ipek ve pamuk karışımından yapılması', 'Tezgâhta çok sık düğümlerle dokunması', 'Yalnızca sentetik liflerden üretilmesi'], 'Keçede yün lifleri sıcak su, sabun, basınç ve sürtünmeyle birbirine geçer. İplik eğrilip dokunmadığı için keçe bir dokuma değildir.'),
  ('Çobanların yağmur ve soğuktan korunmak için giydiği, keçeden yapılmış kolsuz kalın giysiye ne ad verilir?', 'Kepenek', ['Cepken ya da yelek', 'Entari', 'Kaftan'], 'Kepenek su geçirmez ve sıcak tutar; açık havada sürü güden çobanlar için hem giysi hem yatak işlevi görmüştür.'),
  ('Osmanlı\'da 1829\'daki kıyafet düzenlemesiyle sarığın yerine resmî başlık olarak yaygınlaştırılan başlık hangisidir?', 'Fes', ['Kalpak', 'Kavuk', 'Börk'], 'II. Mahmut döneminde devlet görevlileri için fes zorunlu hâle getirilmiştir. Fes, 1925\'teki Şapka Kanunu ile yerini şapkaya bırakmıştır.'),
  ('Zeybek kıyafetinde yer alan, kolları kısa ya da açık, işlemeli kısa ceket hangisidir?', 'Cepken', ['Kaftan', 'Entari', 'Ferace'], 'Cepken, Ege zeybeklerinin geleneksel giyiminde dizlik, kuşak ve başlıkla birlikte giyilen kısa, süslü cekettir.'),
  ('Mor ya da bordo kadife üzerine sırma ile dal ve çiçek motifleri işlenen, özellikle kına gecesinde gelinin giydiği giysi hangisidir?', 'Bindallı', ['Ehram', 'Cepken', 'Üç etek ya da entari'], 'Bindallı adını, üzerine işlenen çok sayıda dal motifinden alır. Anadolu\'da kına gecesinin simgesi hâline gelmiştir.'),
  ('Nişan töreninde nişanlıların yüzüklerini birbirine bağlayan kurdele hangi renktir ve kim tarafından kesilir?', 'Kırmızıdır, genellikle ailenin sözü dinlenen bir büyüğü keser.', ['Beyazdır, her zaman damadın annesi keser.', 'Mavidir, nişanlılar birlikte keser.', 'Yeşildir, törene katılan en küçük çocuk keser.'], 'Yüzükler kırmızı kurdeleyle bağlanır ve kurdeleyi ailenin saygın bir büyüğü keser; böylece nişan resmîleşmiş sayılır.'),
  ('Kına gecesinde avucunu açmayan geline, avucunu açması için kayınvalidesi geleneksel olarak ne verir?', 'Altın ya da para', ['Bir kase lokum', 'Gümüş bir ayna', 'Yeni bir başörtüsü'], 'Gelin, kayınvalidesi avucuna altın ya da para koymadan elini açmaz. Bu adet geline duyulan değeri simgeler; ardından avucuna kına yakılır.'),
  ('Geleneksel düğünlerde damadın gelinin yüzünü ilk kez açtığında ona verdiği armağana ne denir?', 'Yüz görümlüğü', ['Okuntu', 'Kalın', 'Ağırlık'], 'Yüz görümlüğü genellikle bir takı ya da altındır ve gelinin duvağının açıldığı anda verilir.'),
  ('Geleneksel düğünlerde damadın yanında bulunup ona eşlik eden, düğün işlerinde yardımcı olan kişiye ne ad verilir?', 'Sağdıç', ['Yenge', 'Kayın', 'Ebe'], 'Sağdıç, damadın güvendiği bekâr ya da evli arkadaşı ya da akrabasıdır. Gelinin yanındaki yardımcı kadınlara ise yenge denir.'),
  ('Bazı yörelerde yeni gelin, girdiği evin kapısına bal ya da yağ sürer. Bu adetin dile getirdiği dilek nedir?', 'Gelinin evde tatlı dilli ve geçimli olması', ['Evin kışın sıcak tutulması', 'Kapının kolay açılıp kapanması', 'Kötü kişilerin eve girememesi'], 'Bal ve yağ tatlılığı ve yumuşaklığı simgeler. Gelinin yeni ailesiyle uyum içinde, tatlı dilli olması dilenir.'),
  ('Bir köy düğününde gelinin kucağına kısa bir süre küçük bir erkek çocuk verilir. Bu uygulamanın altında yatan inanç nedir?', 'Gelinin ilk çocuğunun sağlıklı ve erkek olması dileği', ['Gelinin çocuk bakımını bilip bilmediğinin aile büyüklerince sınanması', 'Çocuğun gelinin kardeşi olduğunun duyurulması', 'Gelinin düğün boyunca yorulmaması isteği'], 'Bu adet, geleneksel toplumda yeni evlilerin çocuk sahibi olması dileğini yansıtan bir bereket ve çoğalma inancına dayanır.'),
  ('Doğum yapan kadına ve onu ziyarete gelen konuklara ikram edilen, karanfil ve tarçınla hazırlanan kırmızı renkli içecek hangisidir?', 'Lohusa şerbeti', ['Gül şurubu', 'Demirhindi şerbeti', 'Sahlep'], 'Lohusa şerbeti kırmızı şeker, karanfil ve tarçınla hazırlanır. Kırmızı rengi, anneyi kötülüklerden koruyacağına inanılan "al" renkle de ilişkilidir.'),
  ('Yeni doğan bebeğe ad konurken geleneksel olarak ne yapılır?', 'Kulağına ezan okunup adı üç kez söylenir.', ['Ad, bir kâğıda yazılıp yastığının altına konur.', 'Adı belirlemek için ailede kura çekilir.', 'Bebek ilk kez yıkanırken ad yüksek sesle haykırılır.'], 'Ailenin büyüğü ya da imam bebeğin kulağına ezan okur ve adını üç kez söyler.'),
  ('Bazı yörelerde bebeğin kurumuş göbek bağı bir okul bahçesine ya da cami avlusuna gömülür. Bu uygulamanın ardındaki inanç nedir?', 'Çocuğun ilgisinin ve geleceğinin o yere bağlanacağı', ['Göbek bağının kötü ruhları çekeceği', 'Toprağın böylece daha verimli olacağı', 'Bebeğin daha erken yürüyeceği'], 'Göbek bağı gömülen yerin çocuğun yazgısını etkileyeceğine inanılır: okul bahçesi okumaya, cami avlusu dindarlığa yorulur.'),
  ('Sünnet çocuğunun omzuna ya da başlığına, onu nazardan korumak için takılan ve üzerinde "Allah dilemiş" anlamına gelen bir söz yazan süse ne ad verilir?', 'Maşallah', ['Muska ya da nazarlık', 'Tuğra', 'Rozet'], 'Bu süse üzerindeki sözden dolayı maşallah denir. Çocuğu kıskanç bakışlardan ve nazardan korumaya yönelik bir uygulamadır.'),
  ('Askere gidecek gençlerin eline kına yakılması geleneğinin dayandığı düşünce nedir?', 'Vatan için kendini adamaya hazır, değerli biri olarak görülmesi', ['Askerlikte ellerinin kirlenmemesinin sağlanması', 'Askerin kışlada kolayca tanınması', 'Gencin yakında evleneceğinin duyurulması'], 'Kına, Türk kültüründe adanmışlığı ve değeri simgeler. Kurbanlığa ve geline yakıldığı gibi askere de yakılarak kutsal bir göreve gidişi anlatılır.'),
  ('Hacdan dönenlerin evine gelen konuklara geleneksel olarak ikram edilen iki şey hangisidir?', 'Zemzem ve hurma', ['Ayran ve pide', 'Kahve ve lokum', 'Şerbet ve baklava'], 'Hacılar Mekke\'den getirdikleri zemzem suyunu ve hurmayı ziyaretçilere ikram eder; bu, hac yolculuğunun bereketini paylaşmak anlamına gelir.'),
  ('Eski Türk mezarlarının yanına dikilen ve ölen kişinin hayattayken öldürdüğü düşmanları temsil ettiğine inanılan taşlara ne ad verilir?', 'Balbal', ['Kurgan', 'Bengü taş', 'Tamga'], 'Balbalların, öteki dünyada ölen kişiye hizmet edecek düşmanları simgelediğine inanılırdı. Kurgan ise mezar odası üzerine yığılan tümseklerdir.'),
  ('Eski Türk inancında kadınları, çocukları ve doğumu koruduğuna inanılan tanrıça hangisidir?', 'Umay', ['Erlik', 'Ülgen', 'Ay Ata'], 'Umay, bereketin ve analığın koruyucusudur. Erlik ise yeraltı dünyasının ve kötülüğün temsilcisi sayılırdı.'),
  ('Eski Türklerde boyların hayvanlarına ve eşyalarına vurduğu, her boyun kendine ait işaretine ne ad verilirdi?', 'Tamga', ['Ongun', 'Tuğ', 'Balbal'], 'Tamga, boyun kimliğini gösteren bir işarettir. Oğuz boylarının her birinin ayrı tamgası olduğu bilinir; ongun ise boyun kutsal saydığı hayvandır.'),
  ('Eski Türk devlet anlayışında hükümdarın yönetme yetkisinin Gök Tanrı tarafından verildiğine inanılan kavram hangisidir?', 'Kut', ['Töre', 'Yasa', 'Ülüş'], 'Kut, Tanrı\'nın hükümdara bağışladığı yönetme yetkisi ve uğurdur. Töre ise yazısız hukuk kurallarıdır.'),
  ('Ergenekon Destanı\'na göre Türklerin Ergenekon\'dan çıkışı hangi olayla gerçekleşir?', 'Demir dağın eritilmesiyle', ['Bir denizin kurumasıyla', 'Bir ormanın yakılıp açılmasıyla', 'Bir gölün donmasıyla'], 'Destana göre Türkler bir demirci önderliğinde demir dağı körüklerle eritip yol açar ve bir bozkurtun kılavuzluğunda dışarı çıkar.'),
  ('Nevruz kutlamalarında yakılan ateşin üzerinden atlanmasının simgesel anlamı nedir?', 'Eski yılın kötülüklerinden arınmak', ['Yeni gelinlerin seçilmesi', 'Komşulara meydan okumak', 'Kışlık yakacakları denetlemek'], 'Ateş, Türk inancında arındırıcı bir güç sayılır. Ateşin üzerinden atlamak kışın ve kötülüklerin geride bırakılmasını simgeler.'),
  ('Hıdırellez gecesi dileklerin bir kâğıda yazılıp ya da çizilip gömüldüğü yer geleneksel olarak hangisidir?', 'Gül ağacının dibi', ['Evin eşiğinin altı', 'Çeşme yalağının içi', 'Ocağın külleri arası'], 'Gül ağacının Hızır ile bağlantılı olduğuna inanılır. Dilekler sabah gül ağacının dibinden çıkarılıp akan suya bırakılır.'),
  ('Halk inancına göre şubat sonu ve mart başında düşen cemrelerin sırası hangisidir?', 'Havaya, suya, toprağa', ['Önce toprağa, sonra suya, en son havaya', 'Suya, havaya, toprağa', 'Havaya, toprağa, suya'], 'Cemrenin yaklaşık birer hafta arayla önce havaya, sonra suya, en son toprağa düştüğüne ve böylece her şeyin ısındığına inanılır.'),
  ('Halk takviminde kışın en soğuk dönemi olarak bilinen ve "erbain" de denilen kırk günlük süreye ne ad verilir?', 'Zemheri', ['Hamsin', 'Pastırma yazı', 'Kocakarı soğuğu'], 'Zemheri aralık sonundan ocak sonuna dek süren en soğuk dönemdir. Ardından gelen elli günlük dönem ise hamsin diye anılır.'),
  ('Mart ayında havalar ısınmışken birden bastıran soğuğa verilen ad ve buna dayanan halk hikâyesi hangisidir?', 'Kocakarı soğuğu; havayı ısındı sanan yaşlı kadının donması', ['Pastırma yazı; pastırma kurutan kasabın ölümü', 'Kırlangıç fırtınası; kuşların denize düşmesi', 'Zemheri; çobanın kurtlara yem olması'], 'Hikâyeye göre bir yaşlı kadın kışın bittiğini düşünüp sürüsünü otlatmaya çıkarır ama ani soğukta donar. Bu soğuk, adını bu anlatıdan alır.'),
  ('Sonbaharda, ekim sonu ile kasım başında görülen kısa süreli ılık ve güneşli hava dönemine halk arasında ne denir?', 'Pastırma yazı', ['Kocakarı soğuğu', 'Zemheri', 'Cemre'], 'Pastırma yazı, etlerin kurutulup pastırma yapılmasına elverişli olduğu için bu adı almıştır.'),
  ('Türk kahvesi kültürü ve geleneği UNESCO İnsanlığın Somut Olmayan Kültürel Mirası Temsili Listesi\'ne hangi yıl alınmıştır?', '2013', ['2009', '2017', '2021'], 'Türk kahvesi kültürü ve geleneği 2013\'te listeye girmiştir. Liste, kahvenin hazırlanışını, sunuluşunu ve sosyal işlevini birlikte korur.'),
  ('"Kahvaltı" sözcüğünün kökeni olarak hangi açıklama kabul görür?', 'Kahveden önce yenen hafif yemek anlamındaki "kahve altı" sözü', ['Kahve ile birlikte içilen süt anlamındaki "kahve ağı"', 'Kahvenin kavrulduğu ocak anlamındaki "kahve ateşi"', 'Kahve fincanının altlığı anlamındaki "kahve tablası"'], 'Sözcük "kahve" ile "altı" sözcüklerinin birleşmesinden oluşur; kahve içilmeden önce mideyi doyurmak için yenen yemeği anlatır.'),
  ('Türk kahvesi pişirilirken kahvenin kalitesinin en belirgin göstergesi sayılan özellik hangisidir?', 'Fincanda kalın ve kalıcı bir köpük oluşması', ['Kahvenin kaynayıp cezveden taşması', 'Fincanın dibinde hiç telve kalmaması', 'Kahvenin fincana çok sıcak dökülmesi'], 'Kısık ateşte yavaşça pişen kahve yoğun bir köpük tutar. Kaynayıp taşan kahvenin köpüğü kaçar ve tadı bozulur.'),
  ('Bir kişi Türk kahvesini cezvede yüksek ateşte hızla kaynatıyor ve kahve taşıyor. Geleneksel bilgiye göre bu durumda sonuç ne olur?', 'Köpük kaçar, kahvenin tadı ve kıvamı bozulur.', ['Telve tamamen erir ve kahve süzülmeden içilebilir.', 'Kahve daha koyu ve köpüklü olur.', 'Kahvenin kafeini kaybolur ve tatlanır.'], 'Türk kahvesi kısık ateşte, kaynatmadan pişirilir. Hızlı kaynama köpüğü dağıtır ve acı, yanık bir tat bırakır.'),
  ('Türk kahvesinin yanında bir bardak su ikram edilmesi geleneksel olarak en çok hangi amaçla açıklanır?', 'Ağzı temizleyip kahvenin tadının tam alınmasını sağlamak', ['Kahvenin fazla koyu ise suyla inceltilmesini sağlamak', 'Fincanın soğutulması için yanında su bulundurmak', 'Telvenin suyla fincandan temizlenmesini ve kurumasını kolaylaştırmak'], 'Kahveden önce içilen su damağı temizler ve kahvenin aromasının daha iyi algılanmasını sağlar.'),
  ('Güneydoğu Anadolu\'da çok koyu hazırlanan, defalarca kaynatılıp kulpsuz küçük fincanlarda azar azar ikram edilen acı kahve hangisidir?', 'Mırra', ['Menengiç kahvesi', 'Dibek kahvesi', 'Damla sakızlı kahve'], 'Mırra uzun süre kaynatılarak hazırlanan yoğun ve acı bir kahvedir; Şanlıurfa, Mardin gibi illerde konukseverliğin simgesidir.'),
  ('Kahve çekirdeği yerine yabani fıstık ağacının meyvelerinin kavrulup dövülmesiyle hazırlanan içecek hangisidir?', 'Menengiç kahvesi', ['Mırra', 'Dibek kahvesi', 'Salep'], 'Menengiç (bıttım) ağacının meyveleri kavrulup dövülür ve sütle ya da suyla pişirilir. Kafein içermez.'),
  ('Kahve çekirdeklerinin taş bir havanda tokmakla dövülerek hazırlandığı kahveye ne ad verilir?', 'Dibek kahvesi', ['Menengiç kahvesi', 'Mırra', 'Cezve kahvesi'], 'Dibek, taştan oyulmuş büyük havandır. Bu yöntemle dövülen kahve, değirmende çekilenden farklı bir doku ve aroma kazanır.'),
  ('Osmanlı\'da gazete ve kitap okunan, sohbet edilen kahvehanelere verilen ad hangisidir?', 'Kıraathane', ['Meyhane', 'Tekke', 'Kervansaray'], 'Kıraathane "okuma evi" demektir. 19. yüzyılda gazetelerin yaygınlaşmasıyla bu kahvehaneler toplumsal bir buluşma ve haberleşme yeri olmuştur.'),
  ('Osmanlı döneminde kahvehaneler kültür yaşamında hangi işlevi üstlenmiştir?', 'Meddah, Karagöz ve âşık gösterilerinin sergilendiği bir buluşma yeri olmuştur.', ['Yalnızca kahve satan, oturmanın yasak olduğu dükkânlar olmuştur.', 'Devletin vergi topladığı resmî daireler olarak kullanılmıştır.', 'Yalnız tüccarların girebildiği kapalı kulüpler olarak işlemiştir.'], 'Kahvehaneler sohbet, haber alışverişi ve halk eğlencelerinin merkeziydi; özellikle Ramazan gecelerinde Karagöz ve meddah gösterileri yapılırdı.'),
  ('Geleneksel kız isteme sırasında kahvenin gelin adayı tarafından pişirilip sunulması hangi anlamı taşır?', 'Gelin adayının görgüsünün ve evine bağlılığının izlenmesi', ['Gelin adayının ailesinin zenginliğini göstermesi', 'Damat ailesinin gelin adayına armağan getirmesi', 'Görüşmenin bittiğini konuklara bildirmesi'], 'Kahveyi pişirip sunan gelin adayı konukların önüne çıkar; onun hareketleri ve kahvenin kıvamı aile büyükleri tarafından gözlemlenir.'),
  ('Hamamda suyun biriktiği ve tasla alınıp dökündüğü mermer yalağa ne ad verilir?', 'Kurna', ['Göbek taşı', 'Külhan', 'Halvet'], 'Kurnalar sıcaklık bölümünde duvar diplerinde bulunur. Musluklardan akan sıcak ve soğuk su kurnada karışır.'),
  ('Düğünden önce gelin adayının akrabaları ve arkadaşlarıyla birlikte gittiği, türkü ve ikramlarla süren hamam eğlencesine ne ad verilir?', 'Gelin hamamı', ['Kırk hamamı', 'Damat tıraşı ve eğlencesi', 'Kına gecesi'], 'Gelin hamamı, gelinin evlenmeden önce arınmasını ve arkadaşlarıyla vedalaşmasını simgeleyen bir kadın eğlencesidir.'),
  ('Doğumdan kırk gün sonra annenin ve bebeğin hamama götürülmesi geleneğine ne denir?', 'Kırk hamamı', ['Gelin hamamı', 'Bebek kınası', 'Diş hamamı'], 'Lohusalığın sona erdiğini gösteren bu hamamda bebek kırk suyla yıkanır. Böylece anne ve çocuk günlük yaşama döner.'),
  ('Karagöz oyununda Hacivat ile Karagöz arasındaki gülmecenin başlıca kaynağı nedir?', 'Okumuş Hacivat\'ın ağır sözlerini halk adamı Karagöz\'ün yanlış anlaması', ['İki karakterin sürekli birbirine fiziksel şakalar yapması', 'Oyunun tümüyle şarkılı ve danslı olması', 'Karakterlerin seyircilere sorular sorup yarışma düzenlemesi'], 'Hacivat Arapça ve Farsça sözcüklerle süslü konuşur; Karagöz bunları kendi dünyasına göre yorumlayıp yanlış anlar ve çatışma bu söz oyunlarından doğar.'),
  ('Bir Karagöz oyununda Hacivat "Gönlüm hoş değil." diyor; Karagöz de "Ne oldu, gönlün mü kırıldı, tamirciye götürelim." diye yanıt veriyor. Bu konuşmadaki gülmece hangi yolla oluşturulmuştur?', 'Mecaz anlamlı sözün gerçek anlamda anlaşılmasıyla', ['Karakterlerin birbirine vurmasıyla', 'Konuşmanın şarkıyla söylenmesiyle', 'Yabancı bir dilin taklit edilmesiyle'], 'Karagöz, mecaz anlamlı sözü somut bir nesne gibi ele alır. Gölge oyunundaki gülmece sıklıkla bu tür anlam kaymalarına dayanır.'),
  ('Karagöz oyununda tasvirlerin yansıtıldığı beyaz perdeye ne ad verilir?', 'Ayna', ['Göstermelik', 'Şamdan', 'Mukaddime'], 'Perdeye ayna denir; arkasındaki ışıkla tasvirlerin renkli gölgeleri seyirciye yansır. Göstermelik ise oyun başlamadan perdede duran süs tasviridir.'),
  ('Karagöz tasvirleri geleneksel olarak hangi malzemeden yapılır?', 'Işık geçirecek kadar inceltilip boyanan deve derisinden', ['Renkli kumaş parçalarının üst üste dikilmesinden', 'İnce ağaç levhaların oyulup cilalanmasından', 'Kalın mukavvanın kesilip yağlanmasından'], 'Deve derisi işlenip saydamlaştırılır, ardından kök boyalarla renklendirilir. Böylece ışık geçtiğinde perdede renkli görüntüler oluşur.'),
  ('Karagöz oyununda iki karakterin, asıl konuya geçmeden önce birbirleriyle yaptığı ve olay örgüsüyle doğrudan bağlantısı olmayan söyleşmeye ne denir?', 'Muhavere', ['Fasıl', 'Göstermelik', 'Perde gazeli'], 'Muhavere, Karagöz ile Hacivat\'ın karşılıklı konuşmasıdır. Oyunun asıl olayı daha sonra gelen fasıl bölümünde işlenir.'),
  ('Yaygın efsaneye göre Karagöz ile Hacivat hangi kentte yaşamış ve bir yapı inşaatında çalışmıştır?', 'Bursa', ['Edirne', 'Konya', 'Kastamonu'], 'Efsaneye göre ikili Bursa\'da bir cami inşaatında işçidir; şakalarıyla işi aksattıkları için cezalandırılırlar. Onların anısını Şeyh Küşteri gölge oyunuyla yaşatır.'),
  ('Gölge oyununun piri olarak kabul edilen ve Karagöz perdesine onun adına "Küşteri meydanı" denilen kişi kimdir?', 'Şeyh Küşteri', ['Şeyh Hamdullah', 'Yunus Emre', 'Hacı Bektaş-ı Veli'], 'Gelenekte gölge oyununu Bursa\'da ilk kez oynatan kişinin Şeyh Küşteri olduğuna inanılır; perde onun anısına bu adla da anılır.'),
  ('Karagöz oyunlarında elinde şişesiyle sahneye çıkan, kabadayı ve kavgacı tip hangisidir?', 'Tuzsuz Deli Bekir', ['Beberuhi', 'Tiryaki', 'Çelebi'], 'Tuzsuz Deli Bekir korkulan bir kabadayıdır. Çoğu zaman oyunun sonunda çıkıp ortalığı yatıştırır ya da kargaşayı büyütür.'),
  ('Meddahın gösterisi sırasında elinde tuttuğu iki temel araç hangileridir?', 'Mendil ve sopa', ['Saz ve tef', 'Kavuk ve şakşak', 'Ayna ve şamdan'], 'Meddah mendili ter silmek ve bazı karakterleri canlandırmak için, sopayı ise ses çıkarmak ve dikkat çekmek için kullanır.'),
  ('Meddah gösterisini Karagöz ve orta oyunundan ayıran temel özellik hangisidir?', 'Tek bir anlatıcının bütün karakterleri sesiyle ve hareketleriyle canlandırması', ['Gösterinin yalnız tasvirlerle bir perde arkasında yapılması', 'Oyuncuların açık alanda halka biçiminde dizilen seyircilerin ortasında oynaması', 'Gösterinin yalnızca saray düğünlerinde sergilenmesi'], 'Meddah tek kişilik bir anlatı sanatıdır; değişik ağızları ve kişileri taklit ederek hikâyeyi canlandırır.'),
  ('Orta oyununda oyunu yöneten, seyirciyi selamlayan ve Karagöz\'deki Hacivat\'a karşılık gelen tip hangisidir?', 'Pişekâr', ['Kavuklu', 'Zenne', 'Tiryaki'], 'Pişekâr oyunu açar, düzeni sağlar ve elindeki şakşakla ritim tutar. Kavuklu ise Karagöz\'e karşılık gelir.'),
  ('Orta oyununun yazılı bir metne bağlı olmaması oyuncular açısından hangi sonucu doğurur?', 'Oyuncuların doğaçlamayla oyunu seyirciye ve ana göre biçimlendirmesi', ['Oyunun her gösteride hiç değişmeden aynen oynanması', 'Oyuncuların yalnızca ezberlenmiş şiirleri okuması', 'Oyunun yalnız bir yönetmen varken oynanabilmesi'], 'Orta oyununda belli bir olay taslağı vardır ama sözler büyük ölçüde doğaçlamadır. Oyuncular seyircinin tepkisine göre oyunu canlı tutar.'),
  ('Meddahlık geleneğinin anlatıcısı neden en çok kahvehanelerde gösteri yapardı?', 'Kahvehaneler halkın toplanıp sohbet ve eğlence aradığı yerler olduğu için', ['Kahvehanelerde başka bir eğlence türüne izin verilmediği için', 'Meddahlar kahvehane sahiplerinin akrabası olduğu için', 'Saray meddahları yalnız kahvehanelerde görevlendirildiği için'], 'Kahvehaneler geniş bir dinleyici topluluğunu bir araya getirirdi; özellikle Ramazan gecelerinde meddahlar burada hikâyelerini anlatırdı.'),
  ('Karagöz perdesinin arkasında ışık kaynağı olarak geleneksel olarak ne kullanılırdı?', 'Yağ kandili ya da şamdan', ['Güneş ışığı ve ayna', 'Odun ateşi', 'Ay ışığı'], 'Perdenin arkasına konan yağ kandili ya da şamdan, tasvirlerin renkli gölgelerinin perdeye düşmesini sağlardı.'),
  ('Âşıklık geleneğinde bir gencin rüyasında bir pir ya da sevgili elinden içki içip âşık olmasına ne ad verilir?', 'Bade içme', ['Usta malı söyleme', 'Kahvehane icazeti alma', 'Saz çalmaya başlama töreni'], 'Anlatıya göre bade içen genç uyandığında sazı ve sözü olan bir âşığa dönüşür. Bu motif âşık hikâyelerinde çok yaygındır.'),
  ('Âşıkların dudaklarının arasına iğne koyarak söylediği, b, p, m, f, v gibi dudak ünsüzleri içermeyen şiirlere ne ad verilir?', 'Lebdeğmez', ['Tekerleme', 'Ayaklı türkü', 'Cinaslı mani'], 'Lebdeğmez, "dudak değmez" demektir. Dudakları birbirine değdiren sesler kullanılırsa iğne batar; bu, âşığın ustalığını gösteren bir sınavdır.'),
  ('Aşağıdaki dizelerden hangisi bir maninin ilk dizesi olmaya uygun hece sayısına sahiptir?', 'Bahçelerde gül açar', ['Bahçede açan güller sararır solar', 'Sabah olunca bütün kuşlar uyanır', 'Dağlarda kar var'], 'Mani dizeleri 7 hecelidir. "Bah-çe-ler-de-gül-a-çar" 7 hecedir; diğerleri bu ölçüye uymaz.'),
  ('Dört dizeden oluşan bir manide uyak düzeni genellikle nasıldır?', 'aaxa', ['abab ya da çapraz uyak', 'aabb', 'abcb'], 'Manide birinci, ikinci ve dördüncü dizeler uyaklıdır; üçüncü dize serbesttir. Asıl duygu ve düşünce genellikle son iki dizede verilir.'),
  ('"Bir ağaçta on iki dal, her dalda otuz yaprak." bilmecesinin yanıtı hangisidir?', 'Yıl', ['Saat', 'Hafta', 'Mevsim'], 'On iki dal yılın on iki ayını, her daldaki otuz yaprak da ayların yaklaşık otuz gününü anlatır.'),
  ('Akşehir\'deki Nasreddin Hoca türbesinin kapısıyla ilgili anlatılan mizahi özellik nedir?', 'Kapısı kilitli olduğu hâlde çevresinin duvarsız ve açık olması', ['Kapısının yalnızca bayram günlerinde açılması', 'Kapısının tersine, içeriden açılacak biçimde yapılması', 'Kapısında Hoca\'nın eşeğinin heykelinin bulunması'], 'Türbenin önündeki kapı kocaman bir kilitle kapalıdır ama yanları açıktır. Bu durum, Hoca\'nın mizah anlayışına yakışan bir şaka olarak yorumlanır.'),
  ('Nasreddin Hoca\'nın komşusundan ödünç aldığı kazanı içine küçük bir tencere koyarak geri verip "Kazanın doğurdu." dediği fıkranın sonunda Hoca ne der?', '"Doğurduğuna inandın da öldüğüne neden inanmıyorsun?"', ['"Kazanın yaşlıydı, kendiliğinden kırıldı."', '"Komşuluk hakkı için sana bir tencere daha vereyim, kazan kalsın."', '"Kazanın hiç doğurmadı, sen yanlış anladın."'], 'Komşu tencereyi sevinçle kabul eder. Hoca sonra kazanı geri vermeyip "kazanın öldü" deyince itiraz eden komşuya bu yanıtı verir; fıkra açgözlülüğü eleştirir.'),
  ('Nasreddin Hoca\'nın göle maya çaldığı fıkrada "Ya tutarsa!" demesi en çok hangi tutumu anlatır?', 'Olmayacak bir işe yine de umutla girişmeyi', ['Bir işi bilerek yarım bırakmayı', 'Başkalarının emeğini sahiplenmeyi', 'Yoğurdu bozulan biri için üzülmeyi'], 'Gölün mayalanıp yoğurt olmayacağı bellidir. Hoca\'nın yanıtı, sonucu belirsiz de olsa denemekten vazgeçmeyen iyimser bir tutumu simgeler.'),
  ('Nasreddin Hoca\'nın eşeğe ters bindiği fıkrada bu davranışını nasıl açıklar?', 'Öndekilere sırtını dönmemek ve arkadakileri de görebilmek için', ['Eşeğin geri geri yürümeyi daha çok sevmesi yüzünden', 'Güneşin gözünü almasını önlemek amacıyla', 'Yolu öğrencilerine ezberletmek için'], 'Hoca, önüne geçerse öğrencilerine, arkaya geçerlerse kendisine sırt dönülmüş olacağını söyler. Böylece garip görünen davranışa zekice bir gerekçe bulur.'),
  ('Nasreddin Hoca fıkralarını gülmece yönünden ortak kılan özellik hangisidir?', 'Saçma görünen bir durumun ardında düşündürücü bir ders bulunması', ['Fıkraların her zaman bir kahramanlık savaşıyla sona ermesi', 'Hikâyelerin yalnız saray çevresinde geçmesi', 'Fıkraların ezgiyle söylenmek üzere yazılmış olması'], 'Hoca fıkraları ilk anda güldürür; ardından insan davranışları, adalet ve görgü üzerine bir ders verir.'),
  ('Dede Korkut hikâyelerinde Boğaç Han adını nasıl almıştır?', 'Bir boğayı tek başına yenerek', ['Doğduğu gün bir boğa kurban edildiği için', 'Babasının çok sevdiği bir atın adını alarak', 'Bir savaşta düşman kalesini fethederek'], 'Oğuz geleneğinde çocuğa ad, kahramanlık gösterdikten sonra verilirdi. Boğaç, meydanda azgın bir boğayı yenince Dede Korkut ona bu adı verir.'),
  ('Dede Korkut hikâyelerinde tek gözlü dev Tepegöz\'ü öldüren kahraman kimdir?', 'Basat', ['Deli Dumrul', 'Boğaç Han', 'Dirse Han'], 'Basat, Tepegöz\'ün tek gözünü kızgın şişle kör eder ve onu öldürür. Hikâye, Homeros\'un Kiklop anlatısıyla benzerlikleri nedeniyle de ilgi çeker.'),
  ('Dede Korkut Kitabı\'nda "Dede Korkut" kişiliği hikâyelerde genellikle hangi rolü üstlenir?', 'Kahramanlara ad koyan, öğüt veren bilge ozan', ['Bütün savaşlara komuta eden başkomutan', 'Oğuzlara düşman olan kötü büyücü', 'Yalnızca hayvan sürülerini güden ve şarkı söyleyen bir çoban'], 'Dede Korkut, hikâyelerin sonunda gelip boy boylayıp soy soylayan, kahramanlara ad veren ve öğüt veren bilge bir halk ozanıdır.'),
  ('Köroğlu anlatısında kahramanın adını almasının nedeni nedir?', 'Babasının bir bey tarafından gözlerine mil çekilerek kör edilmesi', ['Doğduğunda gözlerinin kapalı olması', 'Bir savaşta kendi gözünü kaybetmesi', 'Kör bir dervişin yanında büyütülmesi'], 'Bolu Beyi, seyisi Yusuf\'un getirdiği tayı beğenmeyip onun gözlerine mil çektirir. Oğlu Ruşen Ali, "kör oğlu" anlamında Köroğlu diye anılır ve öç almaya girişir.'),
  ('Köroğlu\'nun halk arasında sevilmesinin temel nedeni ne olarak açıklanabilir?', 'Zalim beylere karşı yoksulların yanında durması', ['Saraydan yüksek bir makam alması', 'Bütün hayatını ticaretle geçirmesi', 'Yalnızca aşk şiirleri söylemesi'], 'Köroğlu, haksızlığa uğrayanların sesi olarak görülür. Halk hikâyesindeki başkaldırısı onu Anadolu\'nun adalet arayan kahramanı yapmıştır.'),
  ('Burdur, Isparta ve Antalya yöresinde oynanan, bir hayvanın hareketlerini taklit eden oyun türü hangisidir?', 'Teke', ['Horon havası', 'Kafkas oyunu', 'Karşılama havası'], 'Teke oyunlarında oyuncular dağ keçisinin sıçrama ve sekme hareketlerini taklit eder. Oyun, adını Teke yöresinden ve bu hayvandan alır.'),
  ('Doğu Karadeniz\'de horon havalarında kullanılan, keçi ya da koyun derisinden yapılmış torbası olan nefesli çalgı hangisidir?', 'Tulum', ['Sipsi ve çifte', 'Mey ve balaban', 'Kaval ve dilli düdük'], 'Tulumda deri torba havayla doldurulur; çalgıcı torbayı sıkarak sürekli ses elde eder.'),
  ('Kucağa yatırılarak çalınan, tellerine parmaklara takılan yüksüklerle vurulan ve mandallarla perdesi ayarlanan çalgı hangisidir?', 'Kanun', ['Ud ya da kopuz', 'Tanbur ya da cura', 'Santur ya da çeng'], 'Kanun, tahta bir kutu üzerine gerilmiş çok sayıda telden oluşur. Mandallar sayesinde çalarken perde inceliklerine göre ayar yapılabilir.'),
  ('Davul ile zurnanın Anadolu\'da açık havada yapılan düğün, bayram ve güreşlerde birlikte çalınmasının temel nedeni nedir?', 'Seslerinin güçlü olup uzak mesafelere ulaşması', ['Yalnız kapalı mekânlarda iyi duyulmaları', 'Çok yumuşak ve kısık ses çıkarmaları', 'Çalınmalarının hiçbir eğitim ve deneyim gerektirmemesi'], 'Zurnanın keskin sesi ve davulun gür vuruşu kilometrelerce duyulabilir; bu yüzden açık alan eğlencelerinin vazgeçilmez çalgılarıdır.'),
  ('Yağlı güreşte pehlivanların giydiği, manda ya da dana derisinden yapılmış pantolona ne ad verilir?', 'Kıspet', ['Peştamal ve kuşak', 'Potur ve şalvar', 'Kepenek ve dizlik'], 'Kıspet bacağı dize dek saran, sağlam deriden bir giysidir. Yağlı gövdede tutuş zor olduğu için pehlivanlar kıspetten de yararlanır.'),
  ('Ahilikteki "eline, beline, diline sahip ol" ilkesi bir esnaftan ne bekler?', 'Hırsızlık, ahlaksızlık ve kötü sözden uzak durmasını', ['Elleriyle güçlü, beliyle sağlam, diliyle hızlı konuşan biri olmasını', 'Ürününü yalnız el emeğiyle yapıp makineye başvurmamasını', 'Dükkânında yalnızca kendi dilinde konuşan müşteriye satış yapmasını'], 'El hırsızlığı, bel ahlaksızlığı, dil ise yalan ve kötü sözü simgeler. İlke, dürüst ve ahlaklı bir esnaf olmayı öğütler.'),
  ('Bir ahi ustası, müşterisine aldığı ayakkabının kusurunu kendisi söylüyor ve fiyatı düşürüyor. Bu davranış Ahiliğin hangi anlayışına uygundur?', 'Kazançtan önce dürüstlüğü ve müşteri hakkını gözetmek', ['Rakip dükkânları zor durumda bırakmak için fiyat kırmak', 'Ürünlerin hızla elden çıkarılması için indirim yapmak', 'Ustalığını kanıtlamak için müşteriyle tartışmak'], 'Ahilikte esnafın kusurlu malı gizlemesi büyük ayıp sayılırdı. Dürüstlük ve müşteriye karşı sorumluluk, kazançtan önce gelir.'),
  ('Sadaka taşı uygulamasının yardım anlayışı açısından en önemli özelliği nedir?', 'Yardım edenle edilenin birbirini tanımaması ve onurun korunması', ['Bağışların yalnızca devlet görevlilerince toplanması', 'Yardım alanların adlarının bir deftere yazılması', 'Bağışların her ay belirli bir günde dağıtılması'], 'Bu yöntemde kimin verdiği ve kimin aldığı bilinmez; böylece yardım gösterişten arındırılır ve muhtacın utanması önlenir.'),
  ('Osmanlı külliyelerinde yoksullara, yolculara ve öğrencilere ücretsiz yemek dağıtılan bölüme ne ad verilir?', 'İmaret', ['Medrese', 'Darüşşifa', 'Tabhane'], 'İmaret, vakıf gelirleriyle işletilen aşevidir. Darüşşifa hastane, medrese okul, tabhane ise konuk evidir.'),
  ('Osmanlı camilerinin ve medreselerinin dış duvarlarında görülen küçük, süslü kuş evleri hangi anlayışın ürünüdür?', 'Canlılara karşı merhamet ve hayvanlara barınak sağlama düşüncesi', ['Yapıların sağlamlığını ölçmek için konan mimari işaretler', 'Kuşların yapıları kirletmesini önleyen tuzaklar', 'Yalnızca mimarın imzasını taşıyan süs öğeleri'], 'Kuş evleri kuşların kötü havadan korunması için yapılırdı. Bu küçük yapılar, vakıf kültüründeki hayvan sevgisini gösterir.'),
  ('"Misafir umduğunu değil, bulduğunu yer." atasözü ev sahibi ve konuk ilişkisinde hangi beklentiyi dile getirir?', 'Konuğun ev sahibinin sunduğuyla yetinmesi', ['Ev sahibinin konuğa her istediğini hazırlaması', 'Konuğun yemeğini kendisinin getirmesi', 'Ev sahibinin konuğu önceden aramadan ağırlamaması'], 'Atasözü, konuğun beklentilerini değil ev sahibinin olanaklarını esas almasını, ikram edilene saygı göstermesini öğütler.'),
  ('Habersiz ve uzaktan gelen yabancı bir konuğa geleneksel olarak "Tanrı misafiri" denmesi hangi değeri yansıtır?', 'Kim olursa olsun gelen konuğun kutsal sayılıp ağırlanması', ['Konuğun ancak din adamı ise eve alınması', 'Konuğun yalnızca bir gece kalmasına izin verilmesi', 'Yabancıların her zaman kuşkuyla karşılanması'], 'Türk kültüründe kapıya gelen konuk Tanrı\'nın gönderdiği biri sayılır; kim olduğuna bakılmadan yedirilir ve barındırılır.'),
  ('Geleneksel aile sofrasında yemeğe başlama sırasıyla ilgili yaygın kural hangisidir?', 'Sofradaki en yaşlı kişi başlamadan yemeğe el sürülmemesi', ['En küçük çocuğun herkesten önce başlaması', 'Konuğun yemeğini en son yemesi', 'Herkesin istediği zaman başlayıp kalkması'], 'Büyüğe saygının bir göstergesi olarak yemeğe aile büyüğü başlar. Genellikle "besmele" ile başlanır, büyük kalkmadan sofradan kalkılmaz.'),
  ('Konuk evden ayrılırken ev sahibinin arkasından bir tas su dökmesi geleneği hangi dileği simgeler?', 'Yolunun su gibi akıp kolay olması ve sağ salim dönmesi', ['Evin kötü havadan temizlenmesi', 'Konuğun bir daha gelmemesi', 'Kapı önündeki tozun bastırılması'], 'Arkasından su dökmek, gidenin yolunun açık olması ve suyun aktığı gibi sorunsuz biçimde geri dönmesi dileğini anlatır.'),
  ('Kurşun dökme uygulamasında eritilmiş kurşun nereye dökülür?', 'Kişinin başı üzerinde tutulan su dolu kaba', ['Evin kapı eşiğine', 'Ocaktaki küllerin arasına', 'Bir ağacın köküne'], 'Kurşun döken kişi su dolu kabı nazar değdiğine inanılan kişinin başı üzerinde tutar. Suya düşen kurşunun aldığı şekil yorumlanır.'),
  ('Anadolu\'da nazardan korunmak için evlerde ateşte yakılıp dumanı tütsülenen kurutulmuş bitki hangisidir?', 'Üzerlik', ['Kekik ve nane', 'Adaçayı ve ıhlamur', 'Papatya ve gül'], 'Üzerlik otunun tohumları ve kapsülleri ateşe atılınca kokulu bir duman çıkar. Bu dumanın nazarı uzaklaştırdığına inanılır.'),
  ('Manisa\'da her yıl Sultan Camii\'nin kubbesinden halka saçılan, birçok baharattan hazırlanan karışım hangisidir?', 'Mesir macunu', ['Akide şekeri', 'Lokum ve cevizli sucuk', 'Pekmez ve tahin'], 'Mesir macunu, Merkez Efendi\'nin hastalanan Hafsa Sultan için hazırladığı şifalı karışıma dayandırılır. Mesir şenliği 2012\'de UNESCO listesine girmiştir.'),
  ('Düğün ve bayramlarda büyük kazanlarda dövülmüş buğday ve etin uzun süre pişirilmesiyle yapılan, 2011\'de UNESCO listesine giren tören yemeği hangisidir?', 'Keşkek', ['Aşure', 'Tarhana', 'Kuskus'], 'Keşkek geleneği, yemeğin topluca hazırlanmasını, davul-zurna eşliğinde buğdayın dövülmesini ve dağıtılmasını kapsar.'),
  ('Bir öğrenci, UNESCO\'nun somut olmayan kültürel miras listesine aday gösterilecek bir unsur arıyor. Aşağıdakilerden hangisi bu listeye en uygundur?', 'Bir köyde ustadan çırağa aktarılan çömlek yapım bilgisi', ['Bir Roma dönemi tiyatrosunun kalıntıları', 'Bir milli parktaki kanyon ve şelaleler', 'Bir sarayda sergilenen sultan tahtı'], 'Liste, insanların bildiği ve uyguladığı yaşayan geleneği korur. Kalıntılar, doğal alanlar ve müze eşyaları somut niteliktedir.'),
  ('Geleneksel Türk evinde odaların açıldığı, ailenin birlikte vakit geçirdiği ortak alana ne ad verilir?', 'Sofa', ['Yüklük', 'Cumba', 'Serender'], 'Sofa, odaları birbirine bağlayan geniş bir mekândır. Evin planı sofanın konumuna göre iç sofalı, dış sofalı ya da orta sofalı diye sınıflandırılır.'),
  ('Geleneksel Türk evinde gündüz yatakların ve yorganların kaldırıldığı, içinde çoğu zaman küçük bir yıkanma yeri de bulunan duvar dolabına ne ad verilir?', 'Yüklük', ['Musandıra', 'Kiler', 'Sedir'], 'Yüklükteki yıkanma yerine gusülhane denir. Yatakların gündüz kaldırılması, aynı odanın oturma ve yeme alanı olarak da kullanılmasını sağlar.'),
  ('Mardin\'deki geleneksel evlerin büyük ölçüde açık renkli kesme taştan yapılmasını en iyi açıklayan etken hangisidir?', 'Yörede taşın bol bulunması ve sıcak iklimde serin tutması', ['Bölgede ağaç kerestenin çok ucuz olması', 'Taşın kolayca yanıp ısı vermesi', 'Taş evlerin her yıl yeniden yapılabilmesi'], 'Geleneksel konutlar yöredeki malzeme ve iklimle biçimlenir. Mardin\'de bol bulunan kalker taşı kalın duvarlarla yazın serinlik sağlar.'),
  ('Göçebe yaşamda sütün içinde çalkalanarak tereyağı ile ayranın ayrıldığı ağaç ya da deri kaba ne ad verilir?', 'Yayık', ['Kazan', 'Güğüm', 'Kuyruk'], 'Yayıkta çalkalanan yoğurt ya da süt kaymağından tereyağı ayrılır, geriye ayran kalır. Bu işlem göçebe mutfağının temel uygulamalarındandır.'),
  ('Göçebe kültüründe yufka ekmeğinin geniş, ince yuvarlak saç üzerinde pişirilmesinin bu yaşam biçimine uygun yanı nedir?', 'Fırın gerektirmeden her konakta kolayca pişirilebilmesi', ['Ekmeğin pişirilmeden de yenebilmesi', 'Ekmeğin yalnız kentlerde bulunan özel unla ve mayayla yapılması', 'Yufkanın sadece bayramlarda yapılması'], 'Saç taşınabilir ve kısa sürede ısınır. İnce yufka hızlı pişer, kuru saklanabilir ve sonradan nemlendirilerek yenebilir; bu da göçebe yaşamına çok uygundur.'),
  ('Göçebe Yörüklerin ev eşyalarının büyük kısmının dokumadan yapılmasının nedeni ne olabilir?', 'Dokumaların hafif, katlanabilir ve kolay taşınabilir olması', ['Ağaç ve metalin göçebelere satılmasının yasak olması', 'Dokumaların hiç eskimeyip sonsuza dek kullanılması', 'Göçebelerin yerleşik yaşama hiç geçmek istememesi'], 'Sürekli göç eden bir toplulukta eşyanın hafif ve taşınabilir olması gerekir. Kilim, çuval ve heybe gibi dokumalar bu ihtiyacı karşılar.'),
  ('Ramazan davulcusunun bayram sabahı ya da son günlerinde evleri dolaşmasının geleneksel amacı nedir?', 'Ay boyunca verdiği emeğin karşılığında bahşiş toplamak', ['Bayram namazının saatini duyurmak', 'Eski davulunu satmak için alıcı aramak', 'Mahalle sakinlerinin sayısını kaydetmek'], 'Davulcu bir ay boyunca her gece sahura kaldırdığı mahalle sakinlerinden bahşiş ve armağan alır; bu, emeğine duyulan teşekkürün ifadesidir.'),
  ('Mahyanın bir minareden diğerine gerilen iple yapılması ona hangi işlevi kazandırır?', 'Yazının uzaktan ve geniş bir alandan görülebilmesi', ['Minarenin depreme karşı sağlamlaştırılması', 'Ezan sesinin daha uzağa yayılması', 'Kuşların minareye konmasının engellenmesi'], 'Yüksek minareler arasına asılan ışıklı yazı geceleri kentin pek çok yerinden görülür; böylece bir duyuru ve süsleme aracı olur.'),
  ('Selçuklu mimarisinde kapı ve mihrapların çevresinde sık görülen, birbirine geçen çizgilerin oluşturduğu çok kollu yıldızlı süsleme hangisidir?', 'Geometrik geçme yıldız motifi', ['Natüralist manzara resmi', 'Barok kıvrımlı akantus yaprağı', 'Gotik sivri kemer süslemesi'], 'Selçuklu taş işçiliğinde sonsuzluk anlayışını yansıtan geometrik yıldız kompozisyonları kapı ve mihrapları çerçeveler.'),
  ('Osmanlı İstanbul\'unda yangınlara koşan, su pompalarını omuzlarında taşıyan gönüllü itfaiyecilere ne ad verilirdi?', 'Tulumbacı', ['Pazvant ya da bekçi', 'Saka', 'Hamal'], 'Ahşap evlerin yoğun olduğu İstanbul\'da yangınlar büyük tehlikeydi. Tulumbacılar tulumbalarını sırtlayıp koşarak yangın yerine ulaşırdı.'),
  ('Pamuğu ve yünü bir yay aracılığıyla titreterek kabartan ve yorgan, yatak yapımına hazırlayan zanaatkâr kimdir?', 'Hallaç', ['Saka', 'Semerci', 'Nalbant'], 'Hallaç, yayın telini tokmakla titreterek pamuğu atar ve kabartır. Bu yüzden "hallaç pamuğu gibi atmak" deyimi bir şeyi darmadağın etmeyi anlatır.'),
  ('"Hallaç pamuğu gibi atmak" deyimi aşağıdaki durumlardan hangisi için kullanılabilir?', 'Güçlü bir fırtınanın limandaki tekneleri dağıtması', ['Bir öğrencinin ödevini titizlikle bitirmesi', 'Bir terzinin kumaşı ölçüsüne göre biçmesi', 'Bir aşçının yemeği yavaş yavaş pişirmesi'], 'Hallacın attığı pamuk her yana dağılır. Deyim bir şeyi ya da topluluğu dört bir yana savurmayı anlatır.'),
  ('Eşek, katır ve atların sırtına yük taşımak için konan eğerimsi eşyayı yapan zanaatkâra ne denir?', 'Semerci', ['Nalbant ya da nalçacı', 'Saraç', 'Kalaycı'], 'Semer, hayvanın sırtını yükten korur. Saraç ise eğer, koşum ve deri eşya yapan zanaatkârdır.'),
  ('"Hokkabazlık yapmak" deyimi bugün olumsuz bir anlamda kullanılır. Bu anlamın kaynağı hangisidir?', 'Hokkabazların el çabukluğuyla seyirciyi yanıltması', ['Hokkabazların çok ağır işlerde çalışması', 'Hokkabazların yalnızca saraya hizmet etmesi', 'Hokkabazların hiç konuşmadan gösteri yapması'], 'Hokkabazlar küçük hokkalar ve nesnelerle göz yanıltıcı gösteriler yapardı. Deyim, karşısındakini kandırarak çıkar sağlamayı anlatır.'),
  ('Kış aylarında sıcak olarak içilen, orkide yumrusundan elde edilen tozla hazırlanan geleneksel içecek hangisidir?', 'Salep', ['Boza', 'Şıra', 'Ayran'], 'Salep, bazı orkide türlerinin kurutulup öğütülmüş yumrularından yapılır ve sütle pişirilip tarçınla içilir.'),
  ('Bir şirkette çalışanların sık sık kurallara uymadığını gören bir danışman, sorunun üst yönetimden kaynaklandığını söylüyor. Danışmanın görüşünü en iyi destekleyen atasözü hangisidir?', 'Balık baştan kokar.', ['Sürüden ayrılanı kurt kapar ve yalnız bırakır.', 'Komşu komşunun külüne muhtaçtır.', 'Bin bilsen de bir bilene danış.'], 'Bir toplulukta bozulma önce yönetenlerden başlar; atasözü yönetimin örnek olmasının önemini vurgular.'),
  ('Bir sporcu antrenmanlarının zorluğundan yakınırken antrenörü ona hangi atasözünü söylerse sporcunun zahmete katlanması gerektiğini anlatmış olur?', 'Gülü seven dikenine katlanır.', ['Davulun sesi uzaktan hoş gelir, yakından kulak tırmalar.', 'Kendi düşen ağlamaz, kimseye yakınamaz.', 'Ateş olsa cürmü kadar yer yakar.'], 'Güzel bir şeye ulaşmak isteyen, onun getirdiği sıkıntılara da katlanmalıdır.'),
  ('"İt ürür, kervan yürür." atasözünün öğüdü nedir?', 'Değersiz eleştirilere aldırmadan yoluna devam etmek', ['Köpekleri kervanlardan uzak tutmak gerektiğini bilmek', 'Yolculukta her zaman bir bekçi bulundurmayı öğütlemek', 'Kervanların yavaş ilerlediği için sabırlı olmayı anlatmak'], 'Başarılı bir işi kıskanıp karalayanlar olsa da kararlı kişi bunlara kulak asmadan işini sürdürür.'),
  ('Yanlış bir yatırımın zarar ettirdiğini fark eden birine aşağıdaki atasözlerinden hangisi söylenirse ona hemen vazgeçmesi öğütlenmiş olur?', 'Zararın neresinden dönülse kârdır.', ['Sabrın sonu selamettir, beklemek gerekir.', 'Bir musibet bin nasihatten iyidir.', 'Damlaya damlaya göl olur, zamanla kazanılır.'], 'Yanlış bir işte ısrar etmek zararı büyütür; ne kadar erken vazgeçilirse o kadar kazançlı çıkılır.'),
  ('"Taşıma su ile değirmen dönmez." atasözü hangi gerçeği anlatır?', 'Sürekli dış yardımla yürüyen bir iş uzun süre ayakta kalamaz.', ['Değirmenlerin yalnızca nehir kıyılarında kurulabileceğini', 'Su taşımanın değirmencilikten daha kârlı olduğunu', 'Değirmen taşlarının çok ağır olduğunu ve kolay kolay dönmediğini'], 'Değirmeni döndürmek için sürekli akan bir su gerekir. Kalıcı bir kaynağı olmayan, başkasının desteğiyle yürüyen işler sürdürülemez.'),
  ('"Perşembenin gelişi çarşambadan bellidir." atasözü hangi düşünceyi dile getirir?', 'Bir işin sonucu başlangıcından sezilebilir.', ['Haftanın günleri belli bir sırayla birbirini izler.', 'Çarşamba günü yapılan işler perşembeye ertelenmemelidir.', 'Gelecek her zaman belirsizdir ve tahmin edilemez.'], 'Bir olayın nasıl sonuçlanacağı, ilk belirtilerinden anlaşılabilir.'),
  ('Kardeşiyle tartışan bir genç, sorunu dışarıya anlatmadan aile içinde çözmeye karar veriyor. Bu tutum hangi atasözüne uygundur?', 'Kol kırılır, yen içinde.', ['Akıllı düşman akılsız dosttan iyidir.', 'İnsan yedisinde ne ise yetmişinde de odur.', 'Dağ dağa kavuşmaz, insan insana kavuşur.'], 'Yen, giysinin kol kısmıdır. Atasözü, aile ya da yakın çevre içindeki sorunların dışarıya duyurulmadan kendi içinde çözülmesini öğütler.'),
  ('"Öfkeyle kalkan zararla oturur." atasözüne uygun davranış hangisidir?', 'Sinirlendiğinde karar vermeyi ertelemek', ['Öfkesini hemen sözle dile getirmek', 'Haksızlığa uğradığında susup boyun eğmek', 'Tartışmalarda karşı tarafı suçlamak'], 'Öfkeyle verilen kararlar çoğu zaman pişmanlık getirir. Sakinleşmeden önemli bir karar almamak bu öğüdün uygulamasıdır.'),
  ('"İnsan yedisinde ne ise yetmişinde de odur." atasözü hangi görüşü savunur?', 'Kişinin temel huyunun ömür boyu pek değişmediğini', ['İnsanların yaşlandıkça tümüyle başka birine dönüştüğünü', 'Yedi yaşındaki çocukların okula başlaması gerektiğini', 'Yetmiş yaşından sonra kişinin bilgeleştiğini'], 'Atasözü, karakterin küçük yaşta biçimlendiğini ve sonradan kolay kolay değişmediğini anlatır.'),
  ('"Söz ola kese savaşı, söz ola kestire başı." sözü sözün hangi yönünü vurgular?', 'Sözün barıştırıcı da yıkıcı da olabilecek gücünü', ['Savaşların hep sözle başladığını', 'Az konuşanın her zaman kazandığını', 'Sözlerin yazıya geçirilmesi gerektiğini'], 'Yunus Emre\'ye ait bu dizeler, yerinde bir sözün bir kavgayı bitirebileceğini, yanlış bir sözün ise felakete yol açabileceğini anlatır.'),
  ('"İğneyle kuyu kazmak" deyimi hangi tür çalışma için söylenir?', 'Çok sabır ve emek isteyen, yavaş ilerleyen işler için', ['Kısa sürede bitirilen kolay görevler için', 'Yalnızca kuyu kazan işçilerin yaptığı işler için', 'Sonunda hiçbir sonuç vermeyecek boş işler için'], 'Kuyuyu iğneyle kazmak çok uzun sürer; deyim, büyük sabır gerektiren ve emekle ilerleyen işleri anlatır.'),
  ('"Ağzında bakla ıslanmamak" deyimi nasıl bir kişi için kullanılır?', 'Sır tutamayan, duyduğunu hemen söyleyen biri için', ['Az yemek yiyen ve hep aç kalan biri için', 'Çok yavaş ve düşünerek konuşan biri için', 'Kuru baklayı seven biri için'], 'Bakla ağızda ıslanacak kadar bile beklemeden söylenir; deyim, öğrendiğini hemen başkalarına anlatan kişileri tanımlar.'),
  ('Derste çok konuşkan olan bir öğrenci, öğretmenin sorduğu zor soru karşısında sesi soluğu kesilip susuyor. Bu durum hangi deyimle anlatılır?', 'Dut yemiş bülbüle dönmek', ['Ağzı kulaklarına varmak', 'Burnundan kıl aldırmamak ve kibirlenmek', 'Etekleri zil çalmak'], 'Bu deyim, çok konuşan birinin bir anda susup sessizleşmesini anlatır.'),
  ('"Atı alan Üsküdar\'ı geçti." sözü hangi durumda kullanılır?', 'Bir işte iş işten geçtiğinde, artık önlem almanın yararı kalmadığında', ['Uzun bir yolculuğun sonunda dinlenmeye karar verildiğinde', 'At yarışlarında birinci gelen kutlandığında', 'İstanbul\'da yol tarifi verilirken'], 'Söz, fırsatın kaçırıldığını ve olayın sonuçlarının artık geri döndürülemeyeceğini anlatır.'),
  ('Mevlevi semazeninin başına giydiği uzun keçe külaha ne ad verilir?', 'Sikke', ['Kavuk ya da sarık', 'Fes', 'Börk'], 'Sikke keçeden yapılır ve semazenin nefsinin mezar taşını simgeler. Beyaz tennure kefeni, siyah hırka ise mezarı temsil eder.'),
  ('Sema sırasında semazenin sağ elinin göğe açık, sol elinin yere dönük olması neyi simgeler?', 'Tanrı\'dan alınanın halka verilmesini', ['Gündüz ile gecenin birbirini izlemesini', 'Doğu ile batının ayrılığını', 'Yaz ile kışın dengesini'], 'Sağ elle Hak\'tan alınan rahmet, sol elle halka iletilir. Semazen kendisini yalnızca bir aracı olarak görür.'),
  ('Mevlana\'nın ölüm yıl dönümü olan 17 Aralık\'a "düğün gecesi" anlamında verilen ad hangisidir?', 'Şeb-i Arûs', ['Kadir Gecesi', 'Berat Gecesi', 'Aşure Günü'], 'Mevlana ölümü Tanrı\'ya kavuşma olarak görür; bu yüzden ölüm gününe düğün gecesi denir ve her yıl Konya\'da törenlerle anılır.'),
  ('Ege\'de bir hayır ya da ölünün anısı için kurulan kazanlarda kızartılıp sokaktan geçenlere dağıtılan şerbetli hamur tatlısı hangisidir?', 'Lokma', ['Baklava', 'Künefe', 'Kadayıf'], 'Lokma döktürme, özellikle İzmir ve çevresinde yaygın bir hayır geleneğidir. Kim olduğu sorulmadan herkese ikram edilir.'),
  ('Tarhananın yoğurt ve sebzelerle hazırlanıp güneşte kurutulmasının temel nedeni nedir?', 'Uzun süre bozulmadan saklanabilmesi', ['Tadının tatlılaşması', 'Renginin koyulaşması', 'Pişirmeye gerek kalmaması'], 'Kurutma, suyu uzaklaştırarak mikroorganizmaların üremesini engeller. Böylece tarhana aylarca saklanabilir ve kışın çorba olarak pişirilir.'),
  ('Bursa\'nın tarihte ipek ticaretiyle ünlenmesinde etkili olan, kozaların alınıp satıldığı ünlü han hangisidir?', 'Koza Han', ['Büyük Han', 'Rüstem Paşa Hanı', 'Kurşunlu Han'], 'Koza Han, 15. yüzyılda yapılmıştır. Her yıl haziranda koza hasadının ardından burada koza pazarı kurulurdu.'),
  ('Isparta\'nın el sanatları açısından en çok tanındığı dokuma ürünü hangisidir?', 'Halı', ['Telkari', 'Çini', 'Bakır kap'], 'Isparta halıcılığı 19. yüzyılın sonlarından itibaren gelişmiş ve kentin simgelerinden biri olmuştur.'),
  ('"Bal tutan parmağını yalar." atasözü hangi durumu anlatır?', 'Değerli bir işi yöneten kişinin ondan bir pay alması', ['Tatlı yiyeceklerin sağlıklı olması', 'Arıcılığın zor bir meslek olması', 'İnsanın emeğinin hep karşılıksız kalması'], 'Bir kazancın ya da değerli bir şeyin başında bulunan kişi, ondan kendine de bir yarar sağlar. Atasözü çoğu zaman eleştirel biçimde kullanılır.'),
  ('"Üzüm ye, bağını sorma." atasözü hangi tutumu öğütler?', 'Yararlandığın şeyin kaynağını kurcalamamak', ['Bağcılıkla uğraşmak için çok çalışmak', 'Meyvenin kimden alındığını mutlaka sormayı öğütler', 'Yalnızca kendi bağının üzümünü yemek'], 'Bir şeyden yararlanırken onun ayrıntılarını gereksiz yere sorgulamamak gerektiğini anlatır.'),
  ('Nişanlı bir çiftin bayramda birbirine "bayramlık" armağan göndermesi geleneği en çok neyi pekiştirir?', 'İki aile arasındaki bağı ve yakınlığı', ['Ailelerin birbirine olan borcunu', 'Düğün tarihinin ertelenmesini', 'Nişanın bozulduğunu'], 'Bayramlık gönderme, nişanla kurulan akrabalık ilişkisini canlı tutar ve aileleri birbirine yaklaştırır.'),
  ('Türk süslemesinde Anadolu Selçukluları döneminde çok kullanılan ve güç, egemenlik simgesi kabul edilen hayvan motifi hangisidir?', 'Çift başlı kartal', ['Kanatlı at ve tek boynuzlu at', 'Aslan başlı balık', 'Fil ve gergedan'], 'Çift başlı kartal, Selçuklu taş işçiliğinde ve çinilerinde sıkça görülür; iki yönü de denetleyen güçlü bir egemenliği simgeler.'),
  ('Selçuklu ve Osmanlı süslemesinde hayvan biçimlerinden soyutlanmış, kıvrık ve sivri uçlu motiflere ne ad verilir?', 'Rumi', ['Hatai', 'Penç', 'Natüralist'], 'Rumi motifi bir hayvanın kanat ya da gövde çizgisinin soyutlanmasından doğduğu düşünülen kıvrık bir biçimdir.'),
  ('Eski Türklerde savaşta ve törenlerde kullanılan, at kuyruğu kıllarından yapılıp bir direğe bağlanan sancak benzeri simgeye ne ad verilir?', 'Tuğ', ['Tamga', 'Balbal', 'Ongun'], 'Tuğ, hükümdarlık ve komutanlık simgesiydi. Tuğ sayısı makamın yüksekliğini de gösterirdi.'),
  ('Bir kişinin büyükannesinden kalan bakır tencerenin iç yüzeyi kararmış ve yer yer kalayı aşınmış. Bu tencereyi güvenle kullanmak için ne yapması gerekir?', 'Tencereyi yeniden kalaylatmak', ['Tencereyi sirkeyle doldurup bekletmek', 'Tencereyi boyayla kaplamak', 'Tencereyi fırında kızdırıp soğutmak'], 'Kalayı aşınan bakır kap yiyecekle doğrudan temas eder ve sağlığa zararlı olabilir. Kalaycıya götürülüp yeniden kalaylanmalıdır.'),
  ('Türk kültüründe "kırk" sayısının pek çok gelenekte karşımıza çıkmasına örnek olarak aşağıdakilerden hangisi gösterilemez?', 'Hıdırellez\'in 6 Mayıs\'ta kutlanması', ['Lohusalığın kırk gün sürmesi', 'Ölümün ardından kırkıncı günün anılması', 'Kırk gün kırk gece süren düğün anlatıları'], 'Lohusalık, ölüm sonrası anma ve masallardaki düğünler kırk sayısıyla ilgilidir. Hıdırellez\'in tarihi ise kırk sayısıyla ilgili değildir.'),
  ('Küs olan iki komşunun bayramda birbirini ziyaret edip barışması geleneği bayramların hangi toplumsal işlevini gösterir?', 'Kırgınlıkları giderip toplumsal barışı sağlama', ['Ticari ilişkileri yeniden başlatma', 'Komşular arasında arsa paylaşımı yapma', 'Mahallede yeni kurallar belirleme'], 'Bayramlar, dargınlıkların sona erdirildiği, büyüklerin ve komşuların ziyaret edildiği bir barış ve kaynaşma zamanıdır.'),
  ('"Ferman padişahın, dağlar bizimdir." dizesi hangi tutumu dile getirir?', 'Göçebe Türkmenlerin özgürlük ve dağlara bağlılık duygusunu', ['Padişaha sınırsız bağlılığı ve itaati', 'Dağlık yerlerde tarım yapma isteğini', 'Kentli yaşama duyulan özlemi'], 'Dadaloğlu bu dizede, yerleşik hayata zorlanan göçebelerin, devletin buyruğuna karşın dağlarda özgür yaşama kararlılığını anlatır.'),
  ('17. yüzyılda yaşadığı kabul edilen, doğa ve aşk şiirleriyle tanınan, "Karac\'oğlan" mahlasını kullanan ozanın şiirlerinin başlıca konuları nelerdir?', 'Güzellik, doğa ve sevgi', ['Savaş ve kahramanlık', 'Siyasi eleştiri', 'Dinî öğüt, ahlak ve tasavvuf'], 'Karacaoğlan, Çukurova ve Toroslardaki doğayı ve güzelleri içten bir dille anlatmıştır. Halk şiirinde lirizmin en güçlü temsilcilerindendir.'),
  ('Karagöz perdesinde Arnavut, Kastamonulu, Acem, Laz gibi farklı yörelerden tiplerin bulunması ne gösterir?', 'Osmanlı kentlerindeki çok kültürlü yaşamın yansıtıldığını', ['Oyunun yalnızca köylerde oynandığını', 'Karagöz\'ün başka ülkelerde yazıldığını', 'Bu tiplerin hiçbir zaman konuşmadığını'], 'Karagöz, İstanbul gibi kentlerde bir arada yaşayan farklı toplulukların ağızlarını ve huylarını taklit ederek toplumun bir aynası olur.'),
  ('Bağlamanın sapı üzerine bağlanan ve sesin perdelerini belirleyen düğümlü bağlara ne ad verilir?', 'Perde', ['Mızrap', 'Tezene', 'Kulak'], 'Sap üzerine bağlanan perdeler hangi notanın elde edileceğini belirler. Çalgının adının da bu bağlardan geldiği düşünülür.'),
  ('Bir arkadaşının başarısını kıskanıp onu çekiştiren birine "Gülme komşuna" diye başlayan atasözü yerine hangisi söylenirse ona kötülüğün sahibine döneceği hatırlatılmış olur?', 'Eden bulur.', ['Sakla samanı, gelir zamanı; her şeyin bir vakti vardır.', 'Ağlamayan çocuğa meme vermezler, istemek gerekir.', 'Bin bilsen de bir bilene danışmak gerekir.'], '"Eden bulur" sözü, yapılan kötülüğün er geç yapana geri döneceğini anlatır.'),
  ('"Her kuşun eti yenmez." atasözü kimler için söylenir?', 'Kolay boyun eğmeyen, alt edilmesi güç kişiler için', ['Et yemeyi sevmeyen ve sebze ile beslenen kişiler için', 'Kuş avlamayı meslek edinmiş avcılar için', 'Hayvanları seven ve onları koruyan kişiler için'], 'Atasözü, herkesin kolayca kandırılıp yenilemeyeceğini, bazı kişilerin güçlü ve dirençli olduğunu anlatır.'),
  ('"Dervişin fikri ne ise zikri de odur." atasözü ne anlatır?', 'İnsan sürekli düşündüğü şeyi konuşur.', ['Dervişler hiç konuşmadan ibadet eder ve susar.', 'Tekkelerde yalnızca belirli konular tartışılabilir.', 'Fikirlerini yazıya geçirenler unutulmaz ve hatırlanır.'], 'Kişinin aklını meşgul eden konu, sözlerinde de kendini gösterir.'),
  ('Bir aşçının iki çırağından biri ustasını izleyerek, öteki yalnız kitaplardan okuyarak yemek öğreniyor. Ahilik geleneğindeki eğitim anlayışı hangi çırağın yöntemine daha yakındır?', 'Ustasını izleyerek öğrenen çırağın', ['Kitaplardan okuyan çırağın', 'İkisinin de yöntemine eşit uzaklıktadır', 'Kendi kendine deneme yanılmayla öğrenen birinin'], 'Ahilikte meslek ustanın yanında, iş başında, gözlem ve uygulamayla öğrenilir. Bu usta-çırak ilişkisi geleneğin temelidir.'),
  ('Nevruzda bazı yörelerde yumurtaların boyanıp tokuşturulması geleneği neyle ilişkilendirilir?', 'Doğanın yeniden doğuşu ve bereket', ['Kış mevsiminin başlaması', 'Hasat sonu şenlikleri', 'Ölülerin anılması'], 'Yumurta yeni yaşamın simgesidir. Baharın gelişiyle doğanın yeniden canlanması bu simgeyle kutlanır.'),
  ('Yaz aylarında kırk gün boyunca her ikindi vakti yağdığına inanılan yağmurlara verilen halk adı hangisidir?', 'Kırk ikindi yağmurları', ['Kocakarı soğuğu', 'Pastırma yazı', 'Cemre düşmesi'], 'Kırk ikindi yağmurları özellikle yazın öğleden sonra görülen kısa sağanaklardır. "Kırk ikindi" sözü bu yüzden sık ve kısa yağmurları anlatır.'),
  ('Geleneksel Türk evlerinde dışarıdan gelenin içeriyi görmesini engelleyen, pencerelere takılan ahşap ızgaraya ne ad verilir?', 'Kafes', ['Cumba ya da çıkma', 'Saçak', 'Eyvan'], 'Kafes, mahremiyeti korumak için yapılırdı. İçeriden dışarısı görülebilir, dışarıdan ise içerisi seçilemezdi.'),
  ('Geleneksel Türk evlerinde kapıların üzerinde iki ayrı tokmak bulunmasının nedeni olarak anlatılan açıklama hangisidir?', 'Kadın ve erkek konuğun ayrı seslerle haber vermesi', ['Kapının daha sağlam kapanması', 'Gece ve gündüz için farklı tokmakların kullanılması gerekmesi', 'Evin zenginliğini göstermek'], 'Anlatıya göre kalın sesli tokmağı erkekler, ince sesli tokmağı kadınlar çalardı; ev halkı sesten kapıya kimin çıkacağını anlardı.'),
  ('Kapadokya\'da kayaların oyulmasıyla yapılan evlerin yazın serin, kışın ılık olmasının nedeni nedir?', 'Kalın kaya kütlesinin ısıyı yavaş iletmesi', ['Kayaların içinde sıcak su kaynakları bulunması', 'Evlerin her yıl yeniden boyanması', 'Kayaların güneş ışığını tümüyle yansıtması'], 'Kalın tüf kayası ısıyı yavaş iletir; bu yüzden dış sıcaklık değişimleri içeriye çok az yansır.'),
  ('Oya ve dantel gibi el işlerinin genç kızlar tarafından çeyiz için yıllarca hazırlanması geleneği hangi işlevi görürdü?', 'El becerisinin kuşaktan kuşağa aktarılması', ['Bu ürünlerin yalnız pazarda satılması', 'Kızların okula gitmesinin engellenmesi', 'Ailenin borçlarının ödenmesi'], 'Çeyiz hazırlığı sırasında anneler ve büyükanneler kızlara teknikleri öğretir; böylece el sanatları kuşaklar boyunca yaşar.'),
  ('Bir halı uzmanı, bir halının arka yüzüne bakarak düğümleri tek tek sayabildiğini söylüyor. Bu bilgi halı hakkında en çok neyi anlamasına yardım eder?', 'El dokuması olup olmadığını ve sıklığını', ['Halının hangi mevsimde satıldığını', 'Halının sahibinin adını', 'Halının kaç kez yıkandığını'], 'El dokumasında düğümler arka yüzde tek tek seçilir; düğüm sıklığı da kalite hakkında bilgi verir.'),
  ('Bir öğrenci hat levhasında "celî" sözcüğünü görüyor. Bu sözcük yazı hakkında hangi bilgiyi verir?', 'Yazının iri boyutlu yazıldığını', ['Yazının çok küçük yazıldığını', 'Yazının yalnız siyah mürekkeple yazıldığını', 'Yazının bitmemiş olduğunu'], 'Celî, yazının büyük boyutlu biçimidir. Celî sülüs ve celî divani gibi türler uzaktan okunması gereken kitabelerde kullanılır.'),
  ('Surname adı verilen kitaplarda minyatürlerle anlatılan olaylar genellikle hangileridir?', 'Şehzadelerin sünnet şenlikleri ve saray düğünleri', ['Kuraklık ve salgın hastalıklar', 'Ticaret anlaşmaları ve vergiler', 'Gökyüzü gözlemleri ve haritalar'], 'Surname, şenlik kitabı demektir. Levni\'nin minyatürleriyle süslediği Surname-i Vehbi, III. Ahmet döneminin büyük sünnet şenliğini anlatır.'),
  ('Mezar başında Kur\'an okunması ve helva dağıtılmasının yanında, ölümün ardından belli günlerde topluca dua edilmesi geleneğine örnek olarak hangisi gösterilir?', 'Yedinci, kırkıncı ve elli ikinci günlerde mevlit okutulması', ['Doğumdan sonraki kırkıncı günde hamama gidilmesi', 'Düğün öncesinde kına gecesi yapılması', 'Bayram arifesinde evlerin temizlenmesi'], 'Anadolu\'da ölümün ardından belirli günlerde mevlit okutulur, yemek verilir ve ölen kişi topluca anılır.'),
];
